window.EA_COURSE_V9 = {"version":"10.0","weeks":["להכיר את עולם ההשקעות","מחירים, נתונים ומקורות","תשואה, סיכון ומשמעת","לקרוא את מבנה המחיר","תמיכה, התנגדות ופריצות","ממוצעים נעים וכללי מגמה","מומנטום: RSI ו־MACD","תנודתיות ורצועות מסחר","נזילות ונפח מסחר","תבניות גרף — מה אומר המחקר?","יעילות השוק והטיות אנושיות","לבנות אסטרטגיה לפני המסחר","Backtesting נקי מהטיות","בדיקה מחוץ למדגם","שילוב נתונים יסודיים","שווקים גלובליים ומטבע","ניהול תיק ותקופות משבר","פרויקט מחקר ומבחן מסכם"],"sources":{"cmt":{"name":"CMT Association — יעדי למידה בתוכנית המקצועית","url":"https://cmtassociation.org/cmt-program/learning-objectives/","kind":"מסלול מקצועי","tip":"עיין בסדר הנושאים: יסודות, כלים, יישום ואינטגרציה; אין זה קורס CMT רשמי."},"mit":{"name":"MIT OpenCourseWare — Finance Theory I עם Andrew Lo","url":"https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/pages/video-lectures-and-slides/","kind":"הרצאות מצולמות","tip":"בחר פרק מתאים, למשל Risk and Return או Efficient Markets; ההרצאות באנגלית."},"yale":{"name":"Yale Open Courses — Financial Markets, Robert Shiller","url":"https://oyc.yale.edu/economics/econ-252","kind":"הרצאות אקדמיות","tip":"הקדש זמן להרצאה על יעילות השוק או מימון התנהגותי בהתאם לנושא."},"shiller-video":{"name":"Yale — רשימת הרצאות Financial Markets (2008)","url":"https://openmedia.yale.edu/projects/iphone/departments/econ/econ252.html","kind":"וידאו + תמלילים","tip":"רשימת הרצאות פתוחות עם וידאו ותמליל באנגלית, אם זמין."},"sec":{"name":"SEC EDGAR — דוחות מקוריים של חברות","url":"https://www.sec.gov/search-filings","kind":"דוחות רשמיים","tip":"חפש סימול חברה והשווה סעיפי דוח 10-K או 10-Q; אל תסתמך על סיכום AI בלי בדיקה."},"investor":{"name":"Investor.gov — מבוא להשקעות וניהול סיכון","url":"https://www.investor.gov/introduction-investing","kind":"מדריך ציבורי","tip":"מקור רגולטורי בסיסי להסברים על מוצרים, תכנון וסיכון."},"diversification":{"name":"Investor.gov — הקצאת נכסים ופיזור","url":"https://www.investor.gov/introduction-investing/getting-started/asset-allocation","kind":"מדריך ציבורי","tip":"קרא על הקשר בין אופק ההשקעה, סבילות סיכון ופיזור."},"lo-paper":{"name":"Lo, Mamaysky & Wang (2000) — זיהוי תבניות גרף שיטתי","url":"https://www.nber.org/papers/w7613","kind":"מחקר אקדמי","tip":"קרא תקציר ומתודולוגיה, ובחן הבדל בין מידע סטטיסטי נוסף לרווחיות נטו."},"brock":{"name":"Brock, Lakonishok & LeBaron (1992) — כללי מסחר פשוטים","url":"https://doi.org/10.1111/j.1540-6261.1992.tb04681.x","kind":"מחקר אקדמי","tip":"מחקר היסטורי על ממוצעים ופריצות; הממצאים אינם אישור למסחר רווחי כיום."},"sullivan":{"name":"Sullivan, Timmermann & White (1999/2002) — Data Snooping","url":"https://doi.org/10.1111/0022-1082.00163","kind":"מחקר אקדמי","tip":"בחן איך ריבוי ניסיונות משנה מסקנה לגבי יתרון אסטרטגיה."},"damodaran":{"name":"NYU — Aswath Damodaran, קורסי מימון והערכת שווי","url":"https://pages.stern.nyu.edu/~adamodar/New_Home_Page/onlineclass.htm","kind":"שיעורי וידאו","tip":"מומלץ Foundations of Finance למתחילים, ובהמשך Valuation Online."},"cfa":{"name":"CFA Institute — תוכנית הלימודים והמודולים המעשיים","url":"https://www.cfainstitute.org/programs/cfa-program/curriculum","kind":"מסלול מקצועי","tip":"השווה מטרות למידה, כללי אתיקה, מדידה וניתוח יסודי."},"mit-intro":{"name":"MIT OCW — הרצאת מבוא למימון","url":"https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/pages/video-lectures-and-slides/introduction-and-course-overview/","kind":"וידאו אקדמי","tip":"צפה בקטע על תפקיד המערכת הפיננסית וקשר בין החלטות לסיכון."},"mit-videos":{"name":"MIT OCW — ספריית הרצאות מימון של Andrew Lo","url":"https://ocw.mit.edu/courses/15-401-finance-theory-i-fall-2008/resources/lecture-videos/","kind":"וידאו אקדמי","tip":"בחר Lecture בתחום הנלמד; התכנים באנגלית ועשויים להיות ארוכים משיעור אחד."},"fidelity":{"name":"Fidelity — What Is Technical Analysis?","url":"https://www.fidelity.com/learning-center/trading-investing/technical-analysis/what-is-technical-analysis","kind":"מדריך מקצועי — לא מחקר אקדמי","tip":"העמק בהסברי RSI, MACD, נפח ומושגי תמיכה והתנגדות. מדריך זה אינו הוכחה לרווחיות כלל מסחר."},"bollinger":{"name":"John Bollinger — Bollinger Bands (אתר היוצר)","url":"https://www.bollingerbands.com/","kind":"הסבר המקור של מפתח האינדיקטור","tip":"קרא כיצד המפתח מסביר רצועות דינמיות ותנודתיות. זו פרשנות מקצועית של היוצר, לא ניסוי תשואות נפרד."}},"lessons":[{"id":"01-1","week":1,"slot":1,"title":"למה קיימת הבורסה, ומה באמת קונים במניה?","type":"שוק ומחיר","idea":"מניה היא זכות בעלות חלקית בחברה; מחיר המניה הוא המחיר שבו משתתפים מוכנים להחליף את הבעלות ברגע מסוים, לא מדד ישיר לערך העסק. חברות מנפיקות מניות כדי לגייס הון, ובשוק המשני משקיעים מחליפים ביניהם מניות קיימות. כדאי להפריד בין חברה איכותית, מניה במחיר הוגן ועסקה שמתאימה לאופק שלך — אלה שלוש שאלות שונות.","mechanism":"בורסה מרכזת פקודות קנייה ומכירה תחת כללי מסחר ודיווח. הביקוש וההיצע נקבעים בהשפעת רווחים צפויים, ריבית, סנטימנט, נזילות ומידע חדש. מדד כמו S&P 500 מרכז שורה של מניות לפי כללי מדד; קרן ETF מנסה לעקוב אחר מדד או סל נכסים אך אינה המדד עצמו. המנגנון הזה מסביר מדוע חברה יכולה לפרסם חדשות טובות והמניה בכל זאת לרדת: השוק עשוי כבר לתמחר ציפייה גבוהה יותר.","example":"בדוגמה דמיונית, חברה שווה 100 מיליון ₪ ומחזיקה מיליון מניות: שווי שוק של 100 ₪ למניה. אם משתתפים קונים ב־110 ₪, שווי השוק משתנה ל־110 מיליון ₪ גם בלי שהחברה גייסה שקל חדש.","limitation":"שווי שוק לא מספר כמה מזומן יש לחברה; מחיר שוק עשוי לסטות מהערכות שווי. מחיר בודד גם לא מנבא תשואה עתידית. מתחילים מתיאור זכויות הבעלות וסיכוני העסק, לא מגרף צבעוני.","practice":"בחר חברה ציבורית אחת, מצא את הסימול והבורסה, כתוב מה החברה מוכרת, ומדוע קניית המניה אינה זהה לקניית המוצר שלה.","question":"מה מייצגת מניה רגילה?","choices":["הלוואה בריבית קבועה לחברה","חלק מבעלות בחברה","הבטחה לקבל תשואה חיובית"],"correct":1,"explanation":"מניה מעניקה זכויות בעלות לפי סוג המניה; אין הבטחת תשואה או תשלום קבוע.","sources":["investor","mit-intro"],"objectives":["להסביר במילים שלך: למה קיימת הבורסה, ומה באמת קונים במניה?","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"01-2","week":1,"slot":2,"title":"מניה, אג״ח, ETF ומדד — לא לערבב מוצרים","type":"ניתוח ויישום","idea":"כל נכס מייצג חשיפה אחרת. אג״ח היא התחייבות חוב עם תנאים מוגדרים, מניה היא בעלות, מדד הוא שיטת מדידה, ו־ETF היא קרן נסחרת שמחזיקה או עוקבת אחר סל. ההבחנה חשובה כי המונח ״השקעתי בנאסד״ק״ לא מסביר אם קנית קרן מחקה, מניה בודדת או מוצר ממונף.","mechanism":"במניות התשואה תלויה בהערכת שווי ובחלוקת רווחים; באג״ח חשובים סיכון אשראי, מח״מ וריבית. קרן מדד רחבה מפזרת חלק מהסיכון הספציפי, אך אינה מבטלת סיכון שוק. שני ETF עם שם דומה יכולים להחזיק סל שונה, לגבות דמי ניהול שונים ולהשתמש בגידור מטבע שונה. לפני השוואת תשואות קוראים מה המדד, מטבע הבסיס, שיטת השקלול ועלויות הקרן.","example":"משקיע המחזיק מניית שבבים אחת נחשף גם להנהלת החברה וגם למחזור הענפי; קרן טכנולוגיה מצמצמת את הסיכון לחברה אחת, אך עדיין רגישה לענף הטכנולוגיה כולו.","limitation":"מניות ואג״ח יכולות לרדת יחד בחלק מהתקופות; ETF סקטוריאלי אינו תמיד פיזור מספק. אל תחליף בדיקה של נכסי הבסיס במילה ״קרן״.","practice":"השווה שתי קרנות ETF: מדד, חמש ההחזקות הגדולות, דמי ניהול ומטבע מסחר. הסבר איזו חשיפה כפולה עשויה להיווצר אם תחזיק בשתיהן.","question":"מהי בדרך כלל קרן ETF?","choices":["מדד ללא החזקות","קרן נסחרת שעוקבת אחר סל או אסטרטגיה","פיקדון עם תשואה מובטחת"],"correct":1,"explanation":"ETF הוא כלי השקעה נסחר; חשוב לבדוק את מה שהוא מחזיק ולא רק את שמו.","sources":["investor","diversification","cfa"],"objectives":["להסביר במילים שלך: מניה, אג״ח, ETF ומדד — לא לערבב מוצרים","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"01-3","week":1,"slot":3,"title":"AI בשוק ההון: עוזר מחקר, לא כדור בדולח","type":"AI ומחקר","idea":"מודל שפה יכול להבהיר מושגים, לייצר שאלות בדיקה ולבנות טבלת השוואה, אך הוא עלול להמציא מספרים, מקורות וציטוטים. מי שמתחיל ללמוד השקעות זקוק להרגל של אימות: קודם מסמך מקור, אחריו פרשנות, ורק לאחר מכן החלטה. לא נותנים למודל תפקיד של יועץ שמחליף שיקול דעת.","mechanism":"בקשה טובה כוללת תפקיד מוגבל, מקור נתונים, תאריך, הגדרות ודרישה להבחין בין עובדה, חישוב והשערה. למשל: ״הסבר מה ההבדל בין שווי שוק לשווי פעילות; השתמש רק בדוח שהעליתי, ציין עמודים וסמן מידע חסר״. יש לבדוק ידנית לפחות שני נתונים וכל מקור מצוטט. בקשות ״איזו מניה תעלה מחר״ מניחות ודאות שלא קיימת.","example":"אם AI כותב שהכנסות חברה צמחו ב־35%, פתח את דוח החברה, רשום את ההכנסות בשתי התקופות וחשב בעצמך (חדש−ישן)/ישן. אם הנתונים לא תואמים, התשובה אינה ראיה.","limitation":"גם מודל שמנסח תשובה בטוחה מאוד אינו מקור מוסמך. אין להזין מסמכים אישיים, סיסמאות או פרטי חשבון לשירות שאינך סומך על מדיניות הפרטיות שלו.","practice":"כתוב prompt שמבקש הגדרת מוצר פיננסי עם שתי עובדות בדיקות ומקור ראשוני. נסה לזהות טענה אחת שלא ניתן לאמת.","question":"איזו בקשה ל-AI עדיפה?","choices":["הבטח לי את העסקה שתעלה","תן מקורות ראשוניים, תאריך והבדל בין עובדות להשערות","קבע לפי צבע הגרף"],"correct":1,"explanation":"אימות מבוסס מקורות מפחית את הסיכון להישען על תשובות שגויות.","sources":["mit","sec","investor"],"objectives":["להסביר במילים שלך: AI בשוק ההון: עוזר מחקר, לא כדור בדולח","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"02-1","week":2,"slot":1,"title":"לקרוא נר יפני בלי לנחש את הסיפור","type":"שוק ומחיר","idea":"נר יפני מתאר ארבעה מחירים בתקופה: Open, High, Low, Close. הגוף נמצא בין הפתיחה לסגירה, והפתילים מסמנים את הקיצון. נר ירוק פירושו שהסגירה גבוהה מהפתיחה — לא בהכרח שהמניה עלתה יחסית לסגירת אתמול.","mechanism":"גרף יומי מסכם יום מסחר, ושבועי מסכם שבוע; מעבר ביניהם משנה את מידת הרעש. בגרף מחירים צריכים להיות ברורים ציר הזמן, מטבע המחיר, התאמות לפיצול ודיבידנד, ועיתוי סגירת הנר. ההבחנה בין ״מה המחיר עשה״ לבין ״למה״ חיונית: הגרף מציג עסקאות שהתרחשו, לא מניעים מוכחים של קונים ומוכרים.","example":"אתמול סגירה 105; היום פתיחה 98, שיא 104, שפל 96 וסגירה 101. הנר ירוק (101>98), אבל התשואה מסגירה לסגירה היא (101/105−1)≈‎−3.81%.","limitation":"דפוס נר בודד אינו מספיק לביצוע עסקה. גם צבע וקצב שינוי מוגבלים אם הנתונים מושהים או לא מתואמים לאירועי הון.","practice":"רשום OHLC של שלושה נרות. לכל נר חשב שינוי פתיחה–סגירה וגם סגירה–סגירה; הסבר היכן שני הכיוונים שונים.","question":"נר ירוק מציין ש...","choices":["מחיר הסגירה גבוה מהפתיחה באותה תקופה","מחיר הסגירה גבוה מאתמול בהכרח","נפח המסחר היה גדול"],"correct":0,"explanation":"צבע הנר משווה פתיחה לסגירה של אותו נר בלבד.","sources":["lo-paper","cmt","mit"],"objectives":["להסביר במילים שלך: לקרוא נר יפני בלי לנחש את הסיפור","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"02-2","week":2,"slot":2,"title":"תדירות, מקור מידע, פיצולים ותאריכים","type":"ניתוח ויישום","idea":"לפני כל חישוב על סדרת מחירים צריך לזהות מה עומד מאחוריה. נתונים יומיים, תוך־יומיים ושבועיים אינם רק רמות זום; הם משתמשים בחלונות איסוף שונים ועלולים לשקף זמינות ושעות מסחר שונות. לכל נכס רושמים בורסה, אזור זמן, מטבע, תאריך עדכון ומקור.","mechanism":"פיצול מניות משנה את מספר היחידות ואת המחיר הנקוב ליחידה בלי לשנות באופן ישיר את שווי ההחזקה. סדרה לא מתואמת יכולה להראות ירידה חדה מדומה; סדרה מתואמת מפחיתה עיוותים, אך סוג ההתאמה עצמו חשוב. יש לבדוק גם ימי מסחר חסרים, סגירות כפולות, כרונולוגיה הפוכה ועמודות מספריות שהן טקסט. הנתונים הם חומר הגלם לכל אינדיקטור, וכל טעות בהם עוברת לחישובים.","example":"אם מניה נסחרה ב־200 לפני פיצול 2:1, אחרי הפיצול המחיר התיאורטי הוא כ־100 ומספר המניות כפול. ירידה של 50% בגרף לא מתואם אינה בהכרח הפסד כלכלי.","limitation":"מחיר מעודכן אינו בהכרח נתון בזמן אמת; ספקים שונים מעניקים הרשאות שונות. גם מקור מוכר מחייב בדיקת תאריך ואופן ההתאמה.","practice":"טען קובץ CSV כלשהו וסמן: שם שדה תאריך, שם שדה סגירה, מטבע, סדר תאריכים ותקופה. הצע שתי בדיקות תקינות אוטומטיות.","question":"למה חשוב לבדוק נתוני פיצולים?","choices":["כדי למצוא מניות זולות","כדי למנוע קפיצות מחיר מדומות בחישובים","כי הפיצול מבטיח תשואה"],"correct":1,"explanation":"התאמות הן תנאי לניתוח סדרה רציפה ומדידת תשואה עקבית.","sources":["cmt","sec"],"objectives":["להסביר במילים שלך: תדירות, מקור מידע, פיצולים ותאריכים","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"02-3","week":2,"slot":3,"title":"AI לניקוי נתונים — בדיקות במקום המצאות","type":"AI ומחקר","idea":"אפשר להשתמש ב-AI כדי להציע בדיקות של קובץ נתוני מחירים, אבל אין להניח שפלט המודל כבר ביצע אותן. בקשה תקינה מתחילה בדגימה של שורות אמיתיות ובמילון שדות. המודל מסייע להציע חוקים, והקוד או הגיליון בודקים אותם בפועל.","mechanism":"ארבע בדיקות יסוד: תאריכים תקינים וייחודיים; High≥max(Open,Close); Low≤min(Open,Close); נפח לא שלילי. כדאי להוסיף זיהוי קפיצות חריגות, ימי מסחר חסרים ומחירים חיוביים. כל חריגה צריכה להופיע בדוח עם שורה וערך, לא להימחק אוטומטית. AI יכול להסביר למה תאריך בפורמט אמריקאי מתהפך, אבל עלינו לאשר את הפרשנות.","example":"שורה עם Open=101, High=99, Low=96, Close=100 אינה תקינה, משום שהגבוה אמור להיות לפחות 101. האפשרויות הן מיפוי עמודות שגוי או טעות מקור.","limitation":"אסור ״לתקן״ מחירי שוק על ידי המצאת ערכים חסרים ללא תיעוד. גם החלפת ערך חריג במדיאן יכולה למחוק אירוע שוק אמיתי.","practice":"נסח prompt המייצר רשימת בדיקות ל-CSV, בדוק על שורת הדוגמה, וכתוב איזה תיקון מותר לבצע רק לאחר אימות המקור.","question":"איזה תנאי חייב להתקיים ברשומת OHLC תקינה?","choices":["High קטן מהפתיחה","High גדול או שווה לכל Open,Close,Low","Volume שלילי"],"correct":1,"explanation":"הגבוה הוא המחיר המרבי בתקופה ולכן לא יכול להיות קטן ממחיר הפתיחה או הסגירה.","sources":["cmt","mit"],"objectives":["להסביר במילים שלך: AI לניקוי נתונים — בדיקות במקום המצאות","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"03-1","week":3,"slot":1,"title":"תשואה, תשואה מצטברת וכוחה של ירידה","type":"שוק ומחיר","idea":"תשואה פשוטה לתקופה היא (ערך סוף−ערך התחלה+חלוקות)/ערך התחלה. רצף תשואות מצטבר על ידי כפל (1+r), לא חיבור אחוזים. הפרש בין תשואה נומינלית לריאלית תלוי באינפלציה; הפרש בין תשואה במטבע מקומי לתשואה בשקלים תלוי גם בשער החליפין.","mechanism":"ירידה של 20% דורשת עלייה של 25% כדי לחזור למחיר המקורי: מ־100 ל־80 ואז 80×1.25=100. לכן Drawdown אינו רק מדד לא נעים אלא משתנה שמשפיע על תהליך ההתאוששות. מדידה מקצועית כוללת ציון תקופה, מטבע, דיבידנדים, עלויות ודרך חישוב.","example":"שתי תקופות: +10% ולאחר מכן −10% מניבות 1.10×0.90−1=‎−1%, ולא אפס. התוצאה חושפת מדוע מסחר תנודתי עלול לשחוק הון.","limitation":"תשואות עבר אינן חוזה לעתיד. השוואת מוצרי השקעה עם מטבע או פרק זמן שונים בלי התאמה עלולה להיות מטעה.","practice":"חשב תשואה מצטברת של +8%, −12%, +6%; אחר כך חשב את העלייה הדרושה להתאוששות מירידה של 30%.","question":"אחרי ירידה של 50%, מה העלייה הדרושה לחזרה לנקודת ההתחלה?","choices":["50%","75%","100%"],"correct":2,"explanation":"מחיר של 100 ירד ל־50; כדי לחזור ל־100 נדרשת הכפלה.","sources":["investor","mit"],"objectives":["להסביר במילים שלך: תשואה, תשואה מצטברת וכוחה של ירידה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"03-2","week":3,"slot":2,"title":"סיכון, פוזיציה והפסד מתוכנן","type":"ניתוח ויישום","idea":"סיכון אינו רק תנודתיות. יש סיכון שוק, סיכון לחברה, סיכון נזילות, סיכון מטבע וסיכון שהאסטרטגיה עצמה אינה מתאימה לשוק. במסחר חשוב להפריד בין סכום ההשקעה לבין סכום ההפסד המתוכנן במקרה יציאה.","mechanism":"אם הון התרגול הוא 20,000 ₪ ואתה מתכנן לסכן 0.5% בעסקה, תקציב הסיכון הוא 100 ₪. בהנחה תיאורטית של כניסה ב־100, סטופ ב־95, הסיכון ליחידה 5 ₪, ולכן 20 יחידות. בפועל צריך להביא בחשבון עמלות, החלקה, גאפים ומטבע נכס. בלי הגדרת תרחיש יציאה, היחס ״קניתי רק במעט כסף״ אינו מדד מספק.","example":"לונג עם כניסה 150, סטופ 145 ויעד 160: סיכון ליחידה 5 ורווח פוטנציאלי 10, יחס מתוכנן 2:1. אין להסיק מהיחס את הסתברות ההצלחה.","limitation":"פקודת סטופ אינה מבטיחה מחיר ביצוע. תנועה חדה או נזילות נמוכה עלולות להוביל להפסד גדול מהמתוכנן.","practice":"בחר תרחיש דמיוני וחשב את הכמות לפי 0.5% מהון 20,000 ₪. הוסף מה יקרה אם מחיר היציאה יהיה 2 ₪ גרוע מהסטופ.","question":"מה משפיע על גודל פוזיציה לפי סיכון?","choices":["תקציב הסיכון חלקי מרחק הכניסה–סטופ","הצבע של הנר האחרון","מספר עוקבים של מניה"],"correct":0,"explanation":"כמות יחידות מתוכננת נגזרת מהפסד מרבי רצוי ומסיכון ליחידה, עם התאמה לעלויות.","sources":["investor","cfa"],"objectives":["להסביר במילים שלך: סיכון, פוזיציה והפסד מתוכנן","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"03-3","week":3,"slot":3,"title":"AI בבדיקת חישובים והנחות סיכון","type":"AI ומחקר","idea":"כדי להפוך AI לבקר איכות, מבקשים ממנו לא רק מספר אלא גם נוסחה, יחידות, הנחות וסעיף ״מה עשוי להשתבש״. יש הבדל בין חישוב דטרמיניסטי לבין אומדן הסתברותי. אם תיתן למודל רמת סטופ, ההפסד התיאורטי קל לחישוב; ההפסד בפועל תלוי באופן ביצוע ההוראה.","mechanism":"בניסוי חישובי מבקשים מהמודל שתי שיטות אימות בלתי תלויות. למשל לחשב את מספר היחידות דרך חלוקת תקציב הסיכון בפער המחירים ואז לבצע חישוב הפוך של ההפסד. בשלב הבא מגדירים תרחיש החלקה ועמלות, רושמים את כל התוצאות בטבלה, ומוודאים שיחידת המטבע עקבית.","example":"תיק של 10,000 ₪, סיכון 1%, כניסה 50, סטופ 48: לפי הנחה תיאורטית, 50 יחידות. אם בפועל היציאה ב־47, ההפסד לפני עלויות הוא 150 ₪ — לא 100 ₪.","limitation":"AI לא יודע מראש מה תהיה ההחלקה העתידית, ואסור לכתוב מספרי הסתברות כאילו הם מדודים אם אין בסיס נתונים.","practice":"כתוב prompt שמחשב גודל פוזיציה וגם שני תרחישי החלקה; דרוש דוח הנחות וחישוב הפוך של כל תשובה.","question":"איזה מהבאים הוא אומדן ולא ודאות?","choices":["מרחק סטופ מתוכנן","מספר היחידות הנגזר מהנוסחה","מחיר הביצוע בפועל של סטופ בעת גאפ"],"correct":2,"explanation":"מחיר הביצוע תלוי בנזילות ובתנאי השוק בעת הביצוע.","sources":["mit","investor"],"objectives":["להסביר במילים שלך: AI בבדיקת חישובים והנחות סיכון","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"04-1","week":4,"slot":1,"title":"איך מזהים מגמה באופן שאחרים יכולים לשחזר?","type":"שוק ומחיר","idea":"אמירה כמו ״הגרף נראה שורי״ איננה כלל מחקרי. הגדרת מגמה אמינה צריכה לציין טווח זמן וכלל מדיד, למשל שיאים ושפלים עולים בחלון של חמש תקופות או מחיר מעל ממוצע נע מסוים. כל הגדרה בוחרת היבט אחר של התנועה, ולכן אין מבחן בודד שמתאים לכל נכס.","mechanism":"שיא מקומי יכול להיקבע כמחיר גבוה משני השכנים מכל צד. שיטה זו דורשת המתנה לנרות הבאים כדי לאשר נקודת קיצון — ולכן אסור להעמיד פנים שהשיא זוהה ביום שבו קרה. אפשר לחלופין להשתמש בממוצע נע או בשיפוע רגרסיה; לכל כלל יש השהיה ורגישות לרעש. כדאי לנסח גם ״מתי אהיה מוכן לשנות עמדה״.","example":"שפלים של 100, 104, 108 ושיאים של 110, 115, 118 מתאימים להגדרת מגמה עולה לפי מבנה שיאים ושפלים. אבל ירידה לשפל 103 עשויה לשבור חלק מההגדרות ולא אחרות.","limitation":"שני אנליסטים יכולים להגדיר מגמה שונה אם בחרו חלון אחר. זה לא בהכרח טעות; חובה לציין כללים.","practice":"בחר עשרים נרות בגרף. הגדר מהו שיא מקומי, סמן שני שיאים ושפלים, וכתוב תנאי ברור שישנה את דירוג המגמה.","question":"מה הופך הגדרת מגמה לניתנת לשחזור?","choices":["תיאור אינטואיטיבי בלבד","כלל מספרי, חלון זמן ותנאי הפרכה","ציור חץ בלי נתונים"],"correct":1,"explanation":"כללים ברורים מאפשרים לאנשים אחרים להגיע לאותו סיווג על אותם נתונים.","sources":["cmt","brock"],"objectives":["להסביר במילים שלך: איך מזהים מגמה באופן שאחרים יכולים לשחזר?","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"04-2","week":4,"slot":2,"title":"ריבוי טווחי זמן: למה יומי ושבועי סותרים?","type":"ניתוח ויישום","idea":"מניה יכולה להיות במגמת עלייה בגרף שבועי ובתיקון יורד בגרף יומי. אין סתירה: כל גרף מתאר תנועה ברזולוציה אחרת. הניתוח הנכון מתחיל בשאלה מהו אופק ההחלטה, ולא בתזוזה שרירותית בין תצוגות עד שמוצאים סיפור נוח.","mechanism":"נתח מלמעלה למטה: תאר תחילה את המגמה הרב־חודשית, אחר כך את המבנה השבועי, ולבסוף את נקודות העבודה היומיות. כאשר מחליפים תדירות, צריך לוודא שאינדיקטורים כמו MA20 מחושבים מחדש: MA20 שבועי משקף 20 שבועות, לא 20 ימים. שוני בין טווחים יכול לסמן אי־ודאות גבוהה יותר, לא הזדמנות בהכרח.","example":"משקיע לטווח שלוש שנים שרואה ירידה של 4% בשבוע עשוי לפעול אחרת מסוחר שתכנן עסקה ליומיים. אותה תנודה אינה נושאת אותה משמעות לשניהם.","limitation":"בחירת הטווח לאחר שראינו את התוצאה היא הטיית אישור. הגדירו טווח החלטה מראש ואל תשנו אותו רק כדי להצדיק מסקנה.","practice":"בגרף שבועי ובגרף יומי של אותו נכס: כתוב כיוון מגמה, כלל מדידה ותחום אי־ודאות. מה חשוב יותר לאופק שלך?","question":"למה MA20 שבועי שונה מ־MA20 יומי?","choices":["זה אותו נתון בצבע אחר","20 נרות שבועיים אינם 20 נרות יומיים","אחד מבטיח הצלחה"],"correct":1,"explanation":"הפרש התדירות משנה את התקופה הכלכלית שמכסה הממוצע.","sources":["cmt","mit"],"objectives":["להסביר במילים שלך: ריבוי טווחי זמן: למה יומי ושבועי סותרים?","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"04-3","week":4,"slot":3,"title":"AI כמבקר תרחישים — לא כמכונת אישור","type":"AI ומחקר","idea":"אחד הסיכונים במחקר בעזרת AI הוא ניסוח שאלה שמזמין רק הסכמה. אם השאלה היא ״למה המניה עומדת לפרוץ״, המודל עלול לבחור טיעונים שתומכים בהנחה. עדיף לשאול ״אילו ממצאים תומכים בכל אחד משני התרחישים ומה ישנה את ההחלטה?״","mechanism":"בונים טבלה עם תרחיש עולה, יורד וצדדי. לכל תרחיש רושמים ראיות נצפות, תחומי מחיר שישנו את הערכתנו, ומה חסר בנתונים. נותנים למודל להתנגד להנחות ולזהות קפיצות לוגיות. אם התרחיש מבוסס על אינדיקטור שחושב ממחיר, אין להציג אותו כמקור בלתי תלוי נוסף למחיר עצמו.","example":"במניה שיש בה שיאים עולים אבל נפח מסחר יורד, אפשר לטעון להמשך מגמה וגם להיחלשותה. מחקר אחראי מתעד את שתי הפרשנויות ומבהיר מה יכריע ביניהן.","limitation":"AI יכול לארגן טענות אך לא ״לראות״ נתונים שלא הוזנו אליו. ודא שהמספרים אכן זמינים במקור.","practice":"נסח בקשה לאיתור ראיות נגדיות לניתוח מגמה. בנה שלוש השערות עם תנאי הפרכה, ואז בדוק אחת ידנית.","question":"מהי שאלת AI מחקרית טובה יותר?","choices":["תן לי שלוש סיבות לקנות עכשיו","איזו תצפית תפריך את ההשערה ומה חסר כדי להחליט?","אל תבקר את ההנחות"],"correct":1,"explanation":"הפרכה ואיסוף ראיות נגדיות מפחיתים הטיית אישור.","sources":["yale","lo-paper"],"objectives":["להסביר במילים שלך: AI כמבקר תרחישים — לא כמכונת אישור","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"05-1","week":5,"slot":1,"title":"תמיכה והתנגדות כאזורים, לא מספרים קסומים","type":"שוק ומחיר","idea":"רמות תמיכה והתנגדות מתארות השערה על אזורי מחיר שבהם הופיעו בעבר שינויים במאזן ביקוש והיצע. בפועל עסקאות אינן מתכנסות לקו מדויק, והטווח המתאים תלוי בתנודתיות הנכס ובתדירות הניתוח. יש להתייחס לרמות ככלי ארגוני להערכת תרחיש, לא כחוק פיזיקלי.","mechanism":"אפשר להגדיר אזור לפי שניים־שלושה שיאים או שפלים קרובים, עם רוחב קבוע באחוזים או לפי ATR. כשמסמנים רמה רק אחרי שראו את כל הגרף, נוצר סיכון של דיוק מדומה. תעד את הנרות שהיו זמינים בזמן סימון האזור, את מספר הנגיעות ואת מה ייחשב שבירה. תמיכה או התנגדות יכולה להפוך בהמשך לתפקוד אחר, אך זו תצפית לבדיקה ולא הבטחה.","example":"שפלים של 98.8, 99.4 ו־100.1 עשויים לתמוך באזור 98.5–100.5, לא ב״קו 99.40״ בדיוק של אגורה.","limitation":"כל רמה נשברת לעיתים; רמות שנבחרו אחרי שהמחיר כבר הגיב להן בדרך כלל נראות אמינות מדי.","practice":"בחר אזור תמיכה בגרף. רשום את נרות ההקמה שלו, רוחב האזור ואת תנאי הביטול של ההשערה.","question":"למה עדיף לעיתים לתאר רמת תמיכה כאזור?","choices":["כי מחיר תמיד נע בקו ישר","כי מסחר ותנודתיות אינם מתרכזים במחיר מדויק אחד","כי אז אין סיכון"],"correct":1,"explanation":"אזור מאפשר להציג אי־ודאות בסימון רמות ולא להמציא דיוק מלאכותי.","sources":["cmt","lo-paper"],"objectives":["להסביר במילים שלך: תמיכה והתנגדות כאזורים, לא מספרים קסומים","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"05-2","week":5,"slot":2,"title":"פריצה, בדיקה חוזרת ופריצת שווא","type":"ניתוח ויישום","idea":"פריצה מתרחשת כשהמחיר עובר אזור שהוגדר מראש; אבל עצם המעבר לא מוכיח שהמחיר ימשיך באותו כיוון. כדאי להבחין בין חצייה במהלך הנר לבין סגירה מעל האזור, ולבחון האם נמדדו תנאי נפח ותנודתיות חריגים.","mechanism":"ניתן להגדיר כלל כמו סגירה מעל אזור ההתנגדות בשיעור העולה על חצי ATR, ואז כניסה רק בנר הבא. אם המחיר שב מהר מתחת לאזור, זה עשוי להיות אירוע של פריצת שווא. ההגדרה חייבת להיות מראש כדי שאפשר יהיה לבצע Backtesting; שינוי התנאים לאחר המקרה הופך את הניתוח לסיפור בדיעבד. חשב גם סיכוי־סיכון והתרחיש שבו לא מבצעים עסקה.","example":"התנגדות 100–102. נר נסחר עד 103 אך נסגר ב־101: חצה תוך־יומית, אך לא נסגר מחוץ לאזור. האם זו פריצה? תלוי בהגדרה שנקבעה לפני הבדיקה.","limitation":"״ריטסט״ אינו תנאי קסם; לפעמים לא יגיע, ולפעמים ייכשל. אין לבחור רק את הדוגמאות שבהן עבד.","practice":"כתוב שני כללי פריצה חלופיים לאותו אזור. השווה מה תעשה בכל אחד בשלושת נרות הדוגמה, בלי להזיז כללים בדיעבד.","question":"מה חשוב ביותר כשבודקים פריצה?","choices":["לקבוע הגדרה לפני בחינת התוצאה","להניח שכל מעבר הוא הצלחה","להתעלם מהנר הבא"],"correct":0,"explanation":"הגדרה מראש מאפשרת לבדוק אותות באופן שיטתי, כולל כישלונות.","sources":["cmt","brock"],"objectives":["להסביר במילים שלך: פריצה, בדיקה חוזרת ופריצת שווא","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"05-3","week":5,"slot":3,"title":"AI בכתיבת תוכנית מסחר שניתן להפריך","type":"AI ומחקר","idea":"התפקיד של AI בשיעור הזה הוא להפוך רעיון עמום למסמך פעולה ברור, לא לאשר שעסקה תהיה רווחית. תוכנית טובה מפרטת תנאי כניסה, מנגנון יציאה, תוקף הרעיון, גודל פוזיציה והנחות ביצוע. אם אחת ההגדרות תלויה ב״נראה חזק״, אי אפשר לשחזר אותה.","mechanism":"הצע למודל טיוטה שבה כתוב: ״נכנס אחרי פריצה של התנגדות״. בקש ממנו לזהות כל עמימות: איך נבחרת התנגדות, מה מרחק הפריצה, באיזו תדירות, על איזה מחיר מבצעים, ומתי מבטלים את התרחיש. לאחר התיקון הפוך את הכללים לטבלה שניתן לבדוק על חמש דוגמאות, כולל דוגמאות כושלות.","example":"כלל מדיד: אם שני נרות יומיים נסגרים מעל רמת 102, נבחן כניסה בפתיחת הנר הבא, סטופ מתחת ל־98, ונתעד עלויות. זה עדיין לא אומר שהכלל טוב — רק שאפשר לחקור אותו.","limitation":"תוכניות מסחר עם הרבה תנאים עלולות להתאים באופן מושלם לעבר ולהיכשל בהמשך; פחות תנאים עשויים להיות קלים יותר לבדיקה.","practice":"הזן כלל עמום משלך ובקש רשימת חסרים. ערוך אותו לכלל שניתן ליישם בלי שיקול דעת נוסף, ואז בדוק אם שני אנשים יקבלו אותה החלטה.","question":"איזו תוכנית ניתנת יותר לבדיקה?","choices":["נכנס כשנראה לי חזק","נכנס לפי כלל מחיר ויציאה שנקבעו מראש","נכנס כי AI ממליץ"],"correct":1,"explanation":"כלל מפורש מקטין מרחב פרשנות ומאפשר בדיקה חוזרת.","sources":["cmt","sullivan"],"objectives":["להסביר במילים שלך: AI בכתיבת תוכנית מסחר שניתן להפריך","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"06-1","week":6,"slot":1,"title":"מהו SMA ומה המחיר שאנחנו משלמים על החלקה?","type":"שוק ומחיר","idea":"ממוצע נע פשוט (SMA) של N תקופות הוא סכום N מחירי הסגירה האחרונים חלקי N. הוא מחליק רעש ובכך עוזר לזהות תנועה רחבה, אך במקביל מגיב באיחור לשינויי מחיר. ככל שהחלון ארוך יותר, הסדרה לרוב חלקה יותר והאות מאוחר יותר.","mechanism":"למחקר צריך לכתוב בדיוק מה מחשבים: SMA20 על נתונים יומיים, על מחירי סגירה מתואמים או לא, וכיצד מטפלים בתקופות שבהן יש פחות מ־20 נרות. חציית מחיר מעל SMA אינה ראיה עצמאית — הממוצע נוצר מאותו מחיר עצמו. הדרך לבדוק אם הוא שימושי היא השוואת כלל פעולה מפורש לבנצ׳מרק לאורך תקופה מתאימה, עם עלויות.","example":"חמש סגירות: 10, 11, 12, 13, 14. SMA5=12. אם הסגירה הבאה 19, ממוצע חמש הסגירות האחרונות יהיה (11+12+13+14+19)/5=13.8.","limitation":"במגמה צדית חציות רבות עשויות ליצור סדרת הפסדים. שיפור פרמטר למפרע אינו בהכרח שיפור אמיתי.","practice":"חשב SMA5 עבור שתי סדרות קצרות. השווה את תגובת הממוצע לשינוי חד במחיר ואת המחיר עצמו.","question":"מהו SMA5?","choices":["ממוצע חמש הסגירות האחרונות","מחיר השיא בחמש תקופות","התחזית לחמשת הימים הבאים"],"correct":0,"explanation":"SMA הוא ממוצע תיאורי של מחירי עבר.","sources":["cmt","brock"],"objectives":["להסביר במילים שלך: מהו SMA ומה המחיר שאנחנו משלמים על החלקה?","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"06-2","week":6,"slot":2,"title":"EMA, חציות ודרכי מדידת מגמה","type":"ניתוח ויישום","idea":"ממוצע מעריכי (EMA) נותן משקל גבוה יותר למחירים חדשים בהשוואה ל־SMA באורך דומה. הוא מגיב מהר יותר במקרים רבים, אך גם רגיש יותר לרעש. אין ״מהיר עדיף״ באופן כללי; השאלה היא מה העלות של איחור לעומת אותות שווא.","mechanism":"כלל חצייה נפוץ משתמש בממוצע קצר וארוך: כשהקצר עולה מעל הארוך מתקבל אות לפי כלל המערכת, ולהפך. מחקר Brock ועמיתיו בחן משפחות של כללי ממוצעים ופריצות במדגם היסטורי, אבל אין להסיק ממנו שכל זוג ממוצעים יניב יתרון כיום. בכל בדיקה יש לקבוע האם האות נצפה בסגירה ומבוצע בנר הבא, ומה קורה בזמן שהממוצעים משתווים.","example":"אם EMA10=102 ו־EMA30=100, המסלול הקצר גבוה מהארוך. זו תצפית על מומנטום בעבר, לא הוראת קנייה אוטומטית.","limitation":"התאמת 100 זוגות EMA לאותו מדגם יכולה לבחור במקרה זוג מנצח; צריך תקופת מבחן נפרדת.","practice":"השווה היפותטית חציית SMA10/30 ל־EMA10/30 על אותם נתונים; תעד מספר אותות, אותות שווא והשהיה.","question":"מה נכון לגבי EMA?","choices":["הוא משתמש במחירים עתידיים","הוא נותן לרוב משקל יחסי גבוה למחירים חדשים","הוא מבטיח פחות הפסדים"],"correct":1,"explanation":"הדגש על נתונים חדשים הוא יתרון וחיסרון אפשריים בהתאם לשוק.","sources":["brock","cmt"],"objectives":["להסביר במילים שלך: EMA, חציות ודרכי מדידת מגמה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"06-3","week":6,"slot":3,"title":"AI לניתוח אינדיקטור — ביקורת על מדדים תלויים","type":"AI ומחקר","idea":"מודל יכול להציע הסבר משכנע לכך שממוצע נע, RSI ו־MACD ״מאשרים״ זה את זה. אבל שלושתם מחושבים ממחירי עבר, ולכן אינם שלושה מקורות מידע עצמאיים. תפקיד ה-AI הוא לעזור לזהות את ההנחה הסמויה הזאת ולהציע בדיקה שתפריד בין מה שמדוד למה שנדמה.","mechanism":"לניסוי טוב אפשר לבקש מטריצה: אינדיקטור, נתונים נדרשים, אופן החישוב, זמן תגובה, שוק שבו הוא עלול להיכשל, והאם הוא מוסיף מידע מעבר למחיר. לאחר מכן בקש הצעה למדד שאין בו אותו סוג מידע, למשל מדד נזילות או מידע עסקי, ובדוק אם הוא באמת מוסיף משהו. חשוב שהמודל לא יציג קורלציה סטטיסטית שלא חושבה.","example":"אם המחיר עולה במהירות, SMA עולה, RSI עשוי להיות גבוה ו־MACD חיובי. שלוש התצפיות יכולות לנבוע כולן מאותו אירוע: עליית מחיר.","limitation":"הוספת עוד אינדיקטורים יכולה לייצר ״תחושת ודאות״ בלי לשפר ביצועי אסטרטגיה. אל תמדוד איכות לפי מספר צבעי האותות.","practice":"בנה טבלת תלויות לשלושה אינדיקטורים. שאל את AI אילו ראיות ייחשבו עצמאיות ואילו הן רק חישוב נוסף של אותו מחיר.","question":"למה אי אפשר לספור MA ו־MACD כשתי ראיות עצמאיות לחלוטין?","choices":["כי שניהם מחושבים בעיקר ממחירים","כי אחד אינו מספרי","כי שניהם תמיד זהים"],"correct":0,"explanation":"שני המדדים נגזרים ממחירים ויכולים לשקף אותו שינוי בסיסי.","sources":["cmt","brock"],"objectives":["להסביר במילים שלך: AI לניתוח אינדיקטור — ביקורת על מדדים תלויים","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"07-1","week":7,"slot":1,"title":"RSI: מה המדד מודד ומתי הוא מטעה?","type":"שוק ומחיר","idea":"RSI הוא מתנד מומנטום שמבוסס על היחס בין ממוצעי העליות והירידות בתקופה נבחרת. המדד נע בדרך כלל בין 0 ל־100. רמה מעל 70 מכונה לעיתים קניית־יתר, ומתחת ל־30 מכירת־יתר, אך אף אחת מהן אינה הוראת קנייה או מכירה.","mechanism":"בגרסה המקובלת של Wilder מחשבים ממוצעי רווחים והפסדים לאורך 14 תקופות, יחס RS, ואז RSI=100−100/(1+RS). כאשר המחיר מטפס בהתמדה, RSI יכול להישאר גבוה במשך שבועות. כאשר הוא נופל בעקביות, RSI עלול להישאר נמוך. עדיף לקרוא אותו לצד מגמה, רמות מפתח ותנודתיות. סטייה בין מחיר ל־RSI יכולה להיות אזהרה על שינוי בתנופה, לא הוכחת היפוך.","example":"מניה מגיעה לשיא חדש של 120, אבל RSI יורד מ־76 ל־64. יש היחלשות יחסית במומנטום העליות, אך כל עוד מבנה השיאים והשפלים נשמר, לא הוכח שינוי מגמה.","limitation":"RSI תלוי באורך החלון ובסוג סדרת המחירים. מתנד נמוך בשוק יורד יכול להמשיך לרדת. אין לבחור ספים בדיעבד לפי ההצלחות שראית.","practice":"בגרף יומי מצא שתי תקופות שבהן RSI מעל 70. בדוק האם המחיר ירד מיד, אחרי כמה נרות, או המשיך לעלות; כתוב מסקנה שאינה מבוססת על דוגמה יחידה.","question":"מה המשמעות של RSI מעל 70?","choices":["המחיר חייב לרדת בנר הבא","מומנטום העליות היה חזק יחסית בחלון החישוב","מחיר המניה גבוה מערכה הפנימי"],"correct":1,"explanation":"רמה גבוהה מעידה על התנהגות המחיר בחלון הנבחר, לא על ערך החברה או עתיד ודאי.","sources":["fidelity","cmt","brock"],"objectives":["להסביר במילים שלך: RSI: מה המדד מודד ומתי הוא מטעה?","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"07-2","week":7,"slot":2,"title":"MACD: מגמה, מומנטום ואיתות מאוחר","type":"ניתוח ויישום","idea":"אינדיקטור MACD מודד פער בין שני ממוצעים נעים אקספוננציאליים, לרוב EMA12 פחות EMA26. קו האיתות הוא EMA9 של ה־MACD; ההיסטוגרמה היא ההפרש ביניהם. לכן MACD מגיב בעיקר לשינוי במחיר ובהתאם לכיוון המגמה.","mechanism":"כאשר MACD חוצה את קו האיתות, פירושו שהתנופה היחסית השתנתה לפי אותם חלונות. כאשר הוא מעל אפס, ה־EMA הקצר גבוה מהארוך. שתי תופעות אלה אינן זהות: קו MACD יכול להיות מתחת לאפס ובכל זאת לחצות את האיתות כלפי מעלה. השווה בין חציות לבין תנועת המחיר עצמה כדי לזהות עיכוב.","example":"דוגמה: EMA12=103, EMA26=100 ולכן MACD=3. אם קו האיתות 2.4, ההיסטוגרמה 0.6. זה סימן למומנטום חיובי יחסית, אך לא מדד לתוחלת הרווח.","limitation":"MACD ו־MA אינם ״שני אישורים בלתי תלויים״; שניהם נגזרים מאותם מחירים. בשוק מדשדש יכולה להופיע סדרת חציות ללא מגמה משמעותית.","practice":"בדוק ארבע חציות MACD ושאל: כמה נרות אחרי שינוי המחיר התקבל האיתות? מהו מחיר הכניסה התיאורטי אחרי העלויות?","question":"מה פירוש MACD חיובי?","choices":["EMA קצר גבוה מהארוך","RSI בהכרח מעל 70","רווח מובטח לאחר חציה"],"correct":0,"explanation":"MACD מעל אפס משקף פער חיובי בין שני ממוצעים, בלי לומר מה יקרה בעתיד.","sources":["fidelity","cmt","brock"],"objectives":["להסביר במילים שלך: MACD: מגמה, מומנטום ואיתות מאוחר","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"07-3","week":7,"slot":3,"title":"AI: השוואת אותות בלי ספירת ראיות כפולה","type":"AI ומחקר","idea":"אנליסט עלול לחשוב שקיבל שלושה אישורים חזקים מפני ש־RSI, MACD וממוצע נע כולם מאותתים על עלייה. אולם מדדים אלה משתמשים במידע מחירי חופף, ולכן אישור כפול אינו שקול לשלוש ראיות עצמאיות.","mechanism":"בקש ממודל שפה למפות את הנוסחאות והקלטים של המדדים ולבנות טבלת תלות. עליו להבחין בין מדדים נגזרי מחיר לבין נפח, מבנה עסקי וחדשות בדוקות. לאחר מכן הגדר כלל שמחייב שני תנאים שאפשר למדוד בלי ניסוחים עמומים כגון ״נראה חזק״. שים לב שהמודל אינו מחשב בפועל מתאם או דיוק אם לא סיפקת נתונים.","example":"אם MA20 עולה, MACD מעל אפס ו־RSI=65, שלושתם מתיישבים עם עליות קודמות; מידע על נפח חריג בדוח המקורי הוא ממד שונה, אך גם הוא אינו מבטיח רווח.","limitation":"בלי מערך בדיקה מסודר, AI עלול לנסח הצדקה נאה להחלטה שכבר קיבלת. בקש ממנו בכוונה לכתוב טיעון נגדי.","practice":"כתוב בקשת מחקר עם שני תרחישים: מה מאשש את ההשערה ומה מפריך אותה. סימן אילו נתונים צריך לאסוף ידנית.","question":"מה נחשב בדיקה ביקורתית טובה?","choices":["לתת משקל אחד לכל צבע במסך","למפות קלטים משותפים ולבקש תרחיש מפריך","לבקש מהמודל המלצה חד־משמעית"],"correct":1,"explanation":"תלויות בין אינדיקטורים עלולות לייצר ביטחון שווא.","sources":["mit","lo-paper","cmt"],"objectives":["להסביר במילים שלך: AI: השוואת אותות בלי ספירת ראיות כפולה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"08-1","week":8,"slot":1,"title":"תנודתיות: טווח, סטיית תקן ו־ATR","type":"שוק ומחיר","idea":"תנודתיות מתארת את גודל שינויי המחיר ולא בהכרח את הכיוון שלהם. סטיית תקן של תשואות מודדת פיזור, בעוד ATR הוא מדד טווח ממוצע שמביא בחשבון גם פערים בין ימי מסחר. לכל מדד שימוש שונה.","mechanism":"True Range הוא המקסימום מבין High−Low, |High−Close קודם| ו־|Low−Close קודם|. ATR מחליק את הטווח הזה לאורך חלון, לרוב 14 תקופות. ניהול סיכון באמצעות ATR מתרגם את התנודתיות הנצפית למרחק סטופ אפשרי; הוא אינו מבטיח שהפסד ייעצר שם, במיוחד בפערי פתיחה.","example":"אם ATR יומי של מניה הוא 4 דולר, סטופ במרחק 1 דולר עלול להיות צר בהשוואה לתנועה היומית המקובלת. אולם סטופ 8 דולר מחייב התאמת גודל פוזיציה בהתאם לסיכון הכספי.","limitation":"תנודתיות היסטורית אינה תחזית אמינה לפער פתאומי. ATR בדולרים בין שתי מניות במחירים שונים אינו מדד השוואה נוח ללא נרמול.","practice":"השווה שתי מניות לפי ATR חלקי מחיר. חשב מרחק סטופ שנובע מכללי סיכון ולא רק מבחירת מספר עגול.","question":"מה מודד ATR?","choices":["כיוון המגמה העתידי","טווחי מחיר ממוצעים הכוללים פערים","רווח למניה"],"correct":1,"explanation":"ATR הוא מדד לטווחי מחיר היסטוריים, לא כיוון.","sources":["cmt","mit"],"objectives":["להסביר במילים שלך: תנודתיות: טווח, סטיית תקן ו־ATR","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"08-2","week":8,"slot":2,"title":"Bollinger Bands: מה אומרת רצועה מתרחבת?","type":"ניתוח ויישום","idea":"רצועות Bollinger מציירות ממוצע נע ובדרך כלל שני גבולות במרחק שתי סטיות תקן סביבו. רוחב הרצועות משקף תנודתיות יחסית של המחירים באותו חלון. מחיר שנוגע ברצועה אינו ״חייב״ לחזור לממוצע.","mechanism":"לרוב משתמשים ב־SMA20 ובסטיית תקן של 20 מחירים. בשוק בעל מגמה חזקה המחיר עשוי להצמד לרצועה העליונה או התחתונה, ובשוק מדשדש לעבור מצד לצד. ״כיווץ״ הרצועות מציין ירידה בתנודתיות ההיסטורית, אך לא אומר מה יהיה כיוון הפריצה. חשוב להשוות רוחב רצועות לתקופות קודמות ולא לערך בודד.","example":"אם SMA20=100 וסטיית התקן=3, רצועות בקירוב 94 ו־106. סגירה ב־107 משקפת חריגה ביחס להיסטוריה בחלון, אך אינה ראיה לכך שהמחיר ״יקר מדי״.","limitation":"ההנחה שחיתוך של ±2 סטיות תקן מכיל תמיד 95% מהמחירים אינה תקפה באופן כללי לנתונים סדרתיים שאינם נורמליים. הימנע מהסקה אוטומטית.","practice":"מצא שוק מגמתי ושוק מדשדש. השווה מה קרה אחרי מגע ברצועה העליונה בחמש דוגמאות בכל מצב.","question":"מה מייצג כיווץ הרצועות?","choices":["ירידה בתנודתיות לפי חלון החישוב","מניה זולה בהכרח","אישור לעליות"],"correct":0,"explanation":"רוחב קטן משקף פיזור נמוך יותר של המחירים בחלון.","sources":["bollinger","cmt","mit"],"objectives":["להסביר במילים שלך: Bollinger Bands: מה אומרת רצועה מתרחבת?","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"08-3","week":8,"slot":3,"title":"AI: לבנות תרחישי תנודתיות, לא נבואה","type":"AI ומחקר","idea":"כאשר שוק סוער, קל לבקש מ־AI ״תחזית״ מדויקת. שימוש רציני יותר הוא לבנות תרחישים מותנים: אם התנודתיות תעלה, מה קורה לגודל הפוזיציה? אם יש פער פתיחה, האם תוכנית הסיכון נשארת הגיונית?","mechanism":"כתוב בקשה שמגדירה מחיר כניסה, מרחק סטופ, ATR, הון, סיכון כספי ועמלות. בקש מהמודל להציג נוסחה, תוצאה ועיגול כלפי מטה למספר מניות שלם. לאחר מכן בדוק חישוב ידני ושאל מה יקרה אם היציאה תתבצע 2% מתחת לסטופ. חשוב להבחין בין תרחיש לביצוע אמיתי.","example":"בהון 10,000 דולר ובסיכון 0.5% לעסקה, התקציב הוא 50 דולר. עם כניסה 40 וסטופ 38, גודל פוזיציה מקסימלי לפי מודל פשוט הוא 25 מניות — לפני עלויות והחלקה.","limitation":"אין להניח יציאה בסטופ מתוכנן בעת תנודה חדה. מודל שאינו כולל מרווח קנייה־מכירה ועלויות מציג סיכון חסר.","practice":"צור טבלת שלושה תרחישים: רגיל, תנודתי ופער פתיחה. חשב הפסד כספי בכל אחד והשווה לתקציב.","question":"מה קודם לבחירת גודל הפוזיציה?","choices":["צבע הנר האחרון","תקציב סיכון ומרחק סטופ מתוכנן","מספר עוקבים ברשת"],"correct":1,"explanation":"מספר המניות נגזר מחשיפה כספית וממרחק הסטופ, לא מהעדפה אינטואיטיבית.","sources":["investor","cmt"],"objectives":["להסביר במילים שלך: AI: לבנות תרחישי תנודתיות, לא נבואה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"09-1","week":9,"slot":1,"title":"נפח מסחר: מדד לפעילות, לא הצבעה על כיוון","type":"שוק ומחיר","idea":"נפח מסחר סופר יחידות או ערך שנסחר בתקופה. הוא יכול להאיר חריגות בפעילות, אבל כל עסקה כוללת קונה ומוכר, ולכן נפח גבוה אינו אומר פשוט ״יש יותר קונים״.","mechanism":"כדי לפרש נפח צריך להשוות אותו לבסיס רלוונטי: ממוצע של תקופות דומות, שעה ביום, אירוע דוח או חדשות. שיא נפח ביום ירידה עשוי לייצג פאניקה, חדשות או איזון מחדש. במדדים ומניות דלות סחירות חשוב לבדוק גם את המרווח בין ביקוש להיצע ולא רק עמודות נפח.","example":"מניה נסחרת בדרך כלל מיליון יחידות ביום, וביום דוח נסחרו 4 מיליון. זהו נפח פי ארבעה, אך כדי להבין את האירוע בדוק גם מחיר, פרסומי חברה והאם היה פער פתיחה.","limitation":"נפח אינו אחיד בין בורסות ומוצרים; גם מסחר מחוץ לשעות הרגילות יכול לגרום להבדלים בין אתרים.","practice":"בדוק חמישה ימים עם נפח חריג. רשום לא רק כיוון מחיר אלא גם חדשות מקוריות, מרווח והאם השינוי נמשך.","question":"נפח גבוה מלמד על...","choices":["רמת פעילות מסחר גבוהה","שכל הסוחרים קונים","עלייה מובטחת בשבוע הבא"],"correct":0,"explanation":"נפח מתאר כמות עסקאות, לא נטיית קונים נטו לבדה.","sources":["fidelity","cmt","sec"],"objectives":["להסביר במילים שלך: נפח מסחר: מדד לפעילות, לא הצבעה על כיוון","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"09-2","week":9,"slot":2,"title":"נזילות, מרווח קנייה־מכירה והחלקה","type":"ניתוח ויישום","idea":"נזילות היא היכולת לקנות או למכור כמות רצויה במהירות ובעלות מסחר סבירה. מניה שמציגה גרף יפה אבל מרווח גדול או ספר פקודות דק עשויה להיות קשה למסחר ממשי.","mechanism":"פקודת Market מבקשת ביצוע במחירים הזמינים; פקודת Limit מגדירה מחיר מקסימלי לקנייה או מינימלי למכירה, אך אינה מבטיחה ביצוע. עלויות בפועל כוללות עמלות, מרווח והחלקה. בבדיקת אסטרטגיה יש לייחס אותן לכל כניסה ויציאה ולדאוג שלא מודדים ביצוע במחיר שאי אפשר לקבל.","example":"מחיר Bid=20.00 ו־Ask=20.08; קנייה מידית ב־Ask ומכירה מידית ב־Bid יוצרת עלות התחלתית של 0.08 דולר ליחידה, עוד לפני עמלה.","limitation":"מרווחים יכולים להתרחב במהלך חדשות, שעות מסחר דלות או תנודתיות קיצונית. נתון מחיר אחרון אינו מבטיח מחיר ביצוע.","practice":"חשב עלות עגולה של כניסה ויציאה עבור 100 מניות, בהנחות מרווח של 0.02, 0.08 ו־0.20 דולר.","question":"מה מאפיין פקודת Limit?","choices":["מבטיחה ביצוע בכל מחיר","מגבילה את מחיר הביצוע אך ייתכן שלא תתבצע","מוחקת את המרווח"],"correct":1,"explanation":"מחיר מוגבל אינו מבטיח שהשוק יגיע אליו עם נזילות מספקת.","sources":["investor","cmt"],"objectives":["להסביר במילים שלך: נזילות, מרווח קנייה־מכירה והחלקה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"09-3","week":9,"slot":3,"title":"AI לכתיבת דוח אירוע שוק עם מקורות","type":"AI ומחקר","idea":"כותרת עיתונאית יכולה לגרום לגרף להיראות ״מוסבר״ בדיעבד, אך קשר בזמן אינו בהכרח קשר סיבתי. מחקר איכותי מציג רצף זמנים והבדל בין דיווח ראשוני לפרשנות.","mechanism":"תן למודל שלושה מקורות עם קישורים ותאריכים: הודעת חברה או דוח רגולטורי, סיכום שוק וגיליון OHLCV. בקש טבלה שמפרידה את העובדות מהפרשנויות, את שעת הפרסום משעת תנועת המחיר, ואת המידע שלא ידוע. דרוש ציטוטים קצרים ומאומתים בלבד, לא ניסוחים מומצאים. בסוף כתוב מה עוד דרוש כדי לטעון לסיבתיות.","example":"חברה מפרסמת תוצאות אחרי המסחר. למחרת פתיחה בפער ועם נפח חריג. אפשר לתאר סמיכות, אך כדי להסיק שהדוח הוא הגורם היחיד יש לשלול אירועים חיצוניים.","limitation":"אתר חדשות משני אינו תחליף למסמך מקור בעת בדיקת נתוני רווח או תחזית. אל תקבל אסמכתה ללא כתובת מקור שנפתחת.","practice":"בחר יום חדשות אחד ובנה ציר זמן של שלוש נקודות: פרסום מקור, פתיחה ופער, סגירה; ציין השערה חלופית.","question":"מהי מסקנה מבוססת?","choices":["החדשות גרמו לכל התנודה בוודאות","קיימת סמיכות זמנים; דרוש אימות נוסף","הגרף מוכיח את כוונת הקונים"],"correct":1,"explanation":"הבחנה בין מתאם לסיבתיות היא חלק מהניתוח.","sources":["sec","yale"],"objectives":["להסביר במילים שלך: AI לכתיבת דוח אירוע שוק עם מקורות","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"10-1","week":10,"slot":1,"title":"תבניות גרף: לזהות כללים במקום לראות צורות","type":"שוק ומחיר","idea":"תבניות כמו ראש־וכתפיים, משולשים ותחתית כפולה נפוצות בספרות ניתוח טכני, אבל הפרשנות שלהן עלולה להיות סובייקטיבית. מחקרו של Andrew Lo עם Harry Mamaysky ו־Jiang Wang הדגיש בניית אלגוריתמים לזיהוי דפוסים כדי לבחון אותם באופן סטטיסטי.","mechanism":"כדי לבדוק דפוס מגדירים מראש: מספר מינימלי של נרות, סטייה מותרת בין שיאים או שפלים, קריטריון אישור, נקודת ביטול ותזמון כניסה. רק אז מודדים התפלגות תשואות אחרי הופעתו ומשווים אותה לבסיס מתאים. אם שני אנשים מציירים ״תחתית כפולה״ באופן שונה, אי אפשר לאסוף נתונים אמינים בלי כללים מדידים.","example":"במקום ״ראיתי W״ הגדֵר שני שפלים במרחק 8–40 ימי מסחר, ביניהם שיא, והשפל השני במרחק עד 3% מהראשון; ספור כמה דוגמאות עומדות בהגדרה.","limitation":"תוצאות במחקר היסטורי אינן מבטיחות יתרון אחרי עמלות או בשוק של היום. גם הגדרה מדויקת יכולה להיבנות בטעות מתוך הנתונים שנבדקו.","practice":"צייר דפוס אחד על הגרף וכתוב תנאים מדידים שקובעים אם הוא קיים, מתי בוטל וכיצד תבדוק אותו על 50 מקרים.","question":"מדוע צריך כלל מתמטי לזיהוי תבנית?","choices":["כדי להבטיח ניבוי מדויק","כדי ששני בודקים יזהו אותה באופן עקבי","כי כל תבנית תמיד עובדת"],"correct":1,"explanation":"כללים מפחיתים סובייקטיביות ומאפשרים ניסוי משוחזר.","sources":["lo-paper","cmt"],"objectives":["להסביר במילים שלך: תבניות גרף: לזהות כללים במקום לראות צורות","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"10-2","week":10,"slot":2,"title":"שיעור הצלחה לעומת תוחלת — הטעות הנפוצה","type":"ניתוח ויישום","idea":"רבים מעריכים תבנית לפי מספר העסקאות שהסתיימו ברווח. זה מדד חלקי: אסטרטגיה עם 80% הצלחות יכולה להפסיד כסף אם 20% ההפסדים גדולים מספיק.","mechanism":"תוחלת פשוטה לעסקה היא P(win)×רווח ממוצע − P(loss)×הפסד ממוצע − עלות ממוצעת. אפשר למדוד גם חציון, Drawdown, יחס רווח־הפסד, פיזור לפי תקופה ורגישות לעלויות. נתונים היסטוריים מייצרים התפלגות מדגמית, ולא ערובה לתוחלת עתידית.","example":"ב־100 עסקאות, 70 מנצחות של 10 דולר ו־30 מפסידות של 30 דולר: הרווחים 700, ההפסדים 900, ולכן התוצאה לפני עמלות היא מינוס 200 דולר למרות 70% הצלחות.","limitation":"תוחלת מושפעת ממקרי קיצון ומבחירת תקופת בדיקה. אין להסיק מסקנה ממספר קטן של עסקאות בלבד.","practice":"בנה שני תרחישים: 40% הצלחה עם יחס 1:3 ו־70% הצלחה עם יחס 1:0.5; השווה תוחלת נטו.","question":"איזה נתון לבדו אינו מספיק לקביעת רווחיות?","choices":["אחוז העסקאות הרווחיות","רווח ממוצע והפסד ממוצע יחד","עלויות מסחר"],"correct":0,"explanation":"ללא גדלי רווח והפסד, אחוז הצלחה עלול להטעות.","sources":["cmt","sullivan"],"objectives":["להסביר במילים שלך: שיעור הצלחה לעומת תוחלת — הטעות הנפוצה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"10-3","week":10,"slot":3,"title":"AI במחקר דפוסים: מעיוורון בדיעבד לפרוטוקול","type":"AI ומחקר","idea":"כאשר מראים למודל גרף שכבר עלה, הוא עלול למצוא בו \"תבנית מנצחת\". בדיקה רצינית מסתירה את העתיד בשלב קבלת ההחלטות ומתעדת מה היה ידוע באותה נקודת זמן.","mechanism":"כתוב פרוטוקול שמייצר רשימת תאריכים אקראית, מציג רק נתונים עד כל תאריך, ומחייב סימון החלטה, כניסה, סטופ ומצב ללא עסקה. רק אחר כך נחשפות התוצאות. בקש מהמודל להציע מבחן ביקורת המבוסס על תאריכים אקראיים או כללי בסיס, ולא על התבנית בלבד. הנחה ש\"נראה לי\" אינה משתנה מחקרי.","example":"אם 12 מתוך 20 דפוסים הצליחו, השווה זאת לשיעור ההצלחה של כניסה אקראית באותו שוק ובאותה תקופה; אחרת קשה לקבוע שיש ערך מוסף.","limitation":"בחירה חוזרת של דוגמאות מוצלחות והעלמת כישלונות היא הטיית בחירה. שמור את כל המקרים בסדר הכרונולוגי.","practice":"הכן טבלת מחקר בת 10 שורות שבה אתה מקבל החלטה רק על מידע שהיה זמין באותו תאריך.","question":"מה מונע הטיית ראייה לאחור?","choices":["להסתיר את נרות העתיד בעת קבלת החלטה","לראות קודם את הרווח ואז לבחור כלל","להסיר הפסדים מהטבלה"],"correct":0,"explanation":"החלטה מוקדמת ומתועדת מפחיתה זיהום ממידע עתידי.","sources":["lo-paper","sullivan"],"objectives":["להסביר במילים שלך: AI במחקר דפוסים: מעיוורון בדיעבד לפרוטוקול","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"11-1","week":11,"slot":1,"title":"השערת השוק היעיל ומה היא לא אומרת","type":"שוק ומחיר","idea":"השערת השוק היעיל בגרסאותיה השונות דנה במידת השתקפות המידע במחירים. היא אינה אומרת שכל מחיר תמיד נכון או שאין תנודות חדות; היא שואלת האם אפשר להפיק רווח עודף באופן עקבי ממידע שכבר נגיש.","mechanism":"כדי לבחון יתרון יש להגדיר מהו הבנצ׳מרק: שוק רחב, סיכון בטא, סקטור או אסטרטגיית Buy-and-Hold. תשואה חיובית לבדה אינה עדות ליתרון אם השוק עלה יותר. הספרות על ניתוח טכני מציעה לעיתים ממצאים חיוביים בתקופות נבחרות, אך גם מראה בעיות של התאמת יתר, שונות בין מדגמים ועלויות ביצוע.","example":"אסטרטגיה הרוויחה 8% בשנה שבה המדד עלה 16%. היא הייתה רווחית בכסף מוחלט, אך נחותה מול המדד לפני התאמות סיכון.","limitation":"אין מבחן יחיד שמכריע אם כל השווקים יעילים בכל רגע. מסקנה טובה מציגה הנחות, מדד ייחוס ומגבלות.","practice":"מצא ביצוע שנתי של אסטרטגיית הדגמה והשווה אותו למדד מתאים ולתנודתיות שלה, בלי להסתפק בצבע הירוק.","question":"מה דרוש כדי לטעון ליתרון מסחרי?","choices":["תשואה חיובית חודש אחד","השוואה לבנצ׳מרק מתאים ולעלויות","צילום מסך של עסקה טובה"],"correct":1,"explanation":"יתרון נבחן מול חלופות אמיתיות ובתנאי ביצוע ריאליים.","sources":["mit","yale","sullivan"],"objectives":["להסביר במילים שלך: השערת השוק היעיל ומה היא לא אומרת","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"11-2","week":11,"slot":2,"title":"פסיכולוגיית משקיעים: עיגון, ביטחון יתר והטיית אישור","type":"ניתוח ויישום","idea":"קבלת החלטות פיננסית אינה תהליך חישובי בלבד. אנשים נוטים לעגן במחיר קנייה, לחפש מידע שמאשר עמדה קודמת ולהעריך יתר על המידה יכולת חיזוי לאחר רצף הצלחות.","mechanism":"עיגון על מחיר הקנייה גורם לשאלה ״מתי אחזור לאפס?״ במקום ״האם ההשקעה מתאימה היום?״. הטיית אישור דוחפת לבחור רק גרפים שמחזקים מסקנה שכבר התקבלה. כדי לצמצם זאת מכינים מראש תרחיש בסיס, תרחיש חלופי, תנאי ביטול והחלטה מה לא לעשות. יומן החלטות מספק תיעוד שאפשר לבדוק אחרי התוצאה.","example":"קנית מניה ב־100 והיא ירדה ל־70. מחיר הקנייה הוא אירוע היסטורי בחשבון שלך, אך אינו קובע את ערך החברה ב־70. בדוק את הנחות ההשקעה מחדש.","limitation":"יומן אינו מבטל הטיות אוטומטית; הוא עוזר לזהות אותן אם כותבים את ההנחות לפני ראיית התוצאה.","practice":"קח החלטת השקעה היפותטית וכתוב שני טיעונים בעדה ושניים נגדה, כולל מדד שיגרום לך לשנות דעה.","question":"מה מדגים עיגון?","choices":["התייחסות למחיר הקנייה כאילו הוא מחיר הוגן","בחינת תרחיש חלופי","תיעוד החלטה מראש"],"correct":0,"explanation":"מחיר הקנייה הוא נקודת מוצא אישית, לא הערכת שווי.","sources":["yale","mit"],"objectives":["להסביר במילים שלך: פסיכולוגיית משקיעים: עיגון, ביטחון יתר והטיית אישור","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"11-3","week":11,"slot":3,"title":"AI כמבקר טיעונים והטיות","type":"AI ומחקר","idea":"מודל שפה שימושי במיוחד כמבקר התהליך: הוא מסוגל להצביע על הנחות לא בדוקות ולדרוש ראיות לטענות. כדי שלא יהפוך למכונת אישור, צריך לבקש ממנו לתקוף את התזה במפורש.","mechanism":"הצע תבנית בת חמישה סעיפים: עובדות מקוריות, פרשנות, תרחיש שורי, תרחיש דובי, ותנאים להכרעה. בקש מהמודל לסמן טענות שאינן מגובות במסמך המקור, ולדרג רק את איכות הראיות ולא את ״ההזדמנות״. אל תאפשר לו להשתמש בתשובותיו הקודמות כראיה. בדוק ידנית לפחות שתי טענות.","example":"טענה: ״המחיר מעל MA20 ולכן חייב להמשיך לעלות״. ביקורת נכונה: מדובר בתיאור של 20 נרות קודמים, ונדרש מבחן של הסתברות התוצאות ותרחישי הפסד.","limitation":"גם ביקורת AI יכולה להיות שגויה או שטחית. השתמש בה כרשימת בדיקות ולא כחותמת סמכות.","practice":"כתוב תזה של 100 מילים, בקש מהמודל חמישה כשלים אפשריים, ובדוק אילו מהם נובעים מעובדות ואילו מהשערות.","question":"מה המטרה העיקרית של תהליך ביקורת AI?","choices":["להגיע תמיד להחלטה לקנות","לזהות הנחות ומידע חסר","להחליף מחקר עצמאי"],"correct":1,"explanation":"תהליך טוב משפר את איכות השאלה לפני ההחלטה.","sources":["yale","mit","cfa"],"objectives":["להסביר במילים שלך: AI כמבקר טיעונים והטיות","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"12-1","week":12,"slot":1,"title":"אסטרטגיה כמערכת כללים מלאה","type":"שוק ומחיר","idea":"אסטרטגיה היא לא רק אות כניסה. כדי שניתן יהיה לבדוק אותה צריך להגדיר יקום נכסים, שעות פעולה, כלל כניסה, כלל יציאה, גודל פוזיציה, סיכון, עמלות ומקרים שבהם לא עושים כלום.","mechanism":"כל סעיף צריך להיות מדיד. במקום ״קנה בפריצה יפה״ כתוב ״קנה בפתיחת הנר הבא אם סגירה יומית מעל שיא 20 הימים הקודמים ובנפח מעל פי 1.5 מממוצע 20 יום״. כלל כזה מאפשר בדיקה, אך גם חשוף להטיית בחירת פרמטרים. תיעוד התאריך שבו נכתב הכלל חשוב לא פחות מהכלל עצמו.","example":"כלל לדוגמה: מניות עם מחזור יומי של מעל מיליון דולר, כניסה לפי סגירת יום, יציאה אם המחיר יורד 2ATR מתחת למחיר הכניסה, סיכון 0.5% מההון.","limitation":"כלל מורכב מדי יכול להתאים באופן מושלם לעבר ולהיכשל בעתיד. יש לבחון את התוספת של כל תנאי בנפרד.","practice":"כתוב אסטרטגיית עמוד אחד עם שמונה שדות. מצא שתי החלטות שנותרו עמומות והפוך אותן למדידות.","question":"מה הופך כלל למסחר בר־בדיקה?","choices":["מילים כמו ״נראה חזק״","הגדרות מדידות מראש לכניסה ויציאה","הבטחה לרווח"],"correct":1,"explanation":"ניתן לבדוק כלל רק כשאפשר להכריע באופן עקבי אם התקיים.","sources":["cmt","brock"],"objectives":["להסביר במילים שלך: אסטרטגיה כמערכת כללים מלאה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"12-2","week":12,"slot":2,"title":"ניהול גודל פוזיציה, סטופ ומגבלות תיק","type":"ניתוח ויישום","idea":"סוחר מקצועי מתכנן תחילה כמה הוא עלול להפסיד בתרחיש שנקבע ורק אחר כך כמה יחידות לרכוש. הסיכון לעסקה הוא חלק מהסיכון לתיק כולו, הכולל מתאם בין פוזיציות, נזילות ופערי מחיר.","mechanism":"בדוגמה פשוטה, מספר מניות = תקציב סיכון ÷ (כניסה−סטופ). יש להתחשב גם במגבלת הון, עמלה ועלות מרווח. אם מחזיקים כמה מניות טכנולוגיה מאותו ענף, הפסדים יכולים להתרחש יחד ולכן סיכון של 1% על כל עסקה אינו תמיד סיכון עצמאי. בנוסף, סטופ הוא הוראה תפעולית עם סיכון החלקה, לא פוליסת ביטוח.","example":"תיק של 20,000 דולר, תקציב 0.5% =100 דולר, כניסה 50 וסטופ 46: 25 מניות לפי סיכון, בעלות 1,250 דולר לפני עמלות.","limitation":"סיכון במינוף יכול לחרוג מהסכום שתכננת. נוסחה לימודית אינה המלצה על אחוזי חשיפה אישיים.","practice":"חשב גודל פוזיציה לשלוש עסקאות עם מרחקי סטופ שונים ובדוק האם החשיפות יחד מרוכזות באותו סקטור.","question":"מה עלול להגדיל סיכון מעבר לחישוב הרגיל?","choices":["מתאם גבוה בין פוזיציות ופערי פתיחה","פיזור מלא בין נכסים לא קשורים","רישום תאריך"],"correct":0,"explanation":"ריכוז נכסים והחלקה עלולים להגדיל את ההפסד.","sources":["investor","diversification","cmt"],"objectives":["להסביר במילים שלך: ניהול גודל פוזיציה, סטופ ומגבלות תיק","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"12-3","week":12,"slot":3,"title":"AI לכתיבת ספר כללים של אסטרטגיה","type":"AI ומחקר","idea":"אחת הדרכים הטובות להשתמש ב־AI היא להפוך רעיון לא מוגדר למסמך שאפשר למסור לבודק אחר. מודל שפה מתאים להכנת טופס ולזיהוי סתירות, אבל לא להמצאת תוצאות מחקר.","mechanism":"הגדר לו להתנהג כעורך פרוטוקול: הוא צריך לשאול אילו נתונים זמינים בזמן אמת, מה מחיר הביצוע האפשרי, מה עושים עם נתון חסר ומהו הקריטריון לביטול. בקש גרסת כללים קצרה ורשימת בדיקות. לאחר מכן השווה את הכללים לארבעה צילומי גרף שנבחרו מראש, כולל שני מקרים של ״אין עסקה״.","example":"אם נכתב ״היכנס בחציה של MA20״, המודל צריך לשאול חציה של איזה מחיר, באיזו נקודה בזמן, לפי איזו סדרת מחירים ובאיזו פקודה.","limitation":"ניסוח מדויק עדיין אינו הוכחה לרווחיות. קודם בודקים את ההשפעה במדגם נפרד ובעלויות אמיתיות.","practice":"הגש מסמך אסטרטגיה עם שדות: נכס, חלון נתונים, כללי החלטה, חישוב יחידות, עלויות, השוואה לבנצ׳מרק ומקרי קצה.","question":"מה אסור ל-AI לעשות במחקר כזה?","choices":["להציע שאלות ביקורת","להמציא תשואות היסטוריות ללא נתונים","לשפר ניסוח מדיד"],"correct":1,"explanation":"AI יכול לתמוך בתכנון, אך לא לייצר נתונים או הוכחות שאינן קיימות.","sources":["cmt","sullivan"],"objectives":["להסביר במילים שלך: AI לכתיבת ספר כללים של אסטרטגיה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"13-1","week":13,"slot":1,"title":"מה Backtesting באמת בודק?","type":"שוק ומחיר","idea":"בדיקה היסטורית מדמה ביצוע של כללי מסחר על נתונים מהעבר. המטרה אינה לגלות את האסטרטגיה ״המושלמת״ אלא להבין התנהגות, עלויות, סיכונים ותלות בתקופה.","mechanism":"Backtest אמין דורש נתוני זמן נכונים, היעדר שימוש במידע עתידי, מחיר ביצוע סביר, טיפול בדיבידנדים ובפיצולים, ובדיקת עלויות. קניית מניה לפי סגירת היום על בסיס אותו מחיר סגירה עשויה להיות לא ריאלית אם הכלל תלוי בידיעה שהיום נסגר כך. חלופה היא ביצוע בפתיחת היום הבא ובהנחת החלקה.","example":"אות כניסה התקבל רק בסגירת יום שני. אי אפשר לטעון שקנית בבוקר יום שני על בסיס אות שלא היה ידוע אז. בדיקה בפתיחת יום שלישי משקפת טוב יותר את לוח הזמנים.","limitation":"גם בדיקה עם קוד נטול שגיאות יכולה להיכשל בעתיד, בגלל שינוי משטר שוק או בחירת נתונים מוטה.","practice":"רשום חמש הנחות ביצוע של Backtest קיים. סימן אילו מהן עלולות לייפות תשואה והצע חלופה שמרנית.","question":"מהי הטיית מבט לעתיד?","choices":["שימוש במידע שלא היה זמין בזמן ההחלטה","בדיקת עמלה כפולה","בחירת מניה סחירה"],"correct":0,"explanation":"החלטה היסטורית חייבת להשתמש רק במידע שהיה ידוע אז.","sources":["sullivan","cmt"],"objectives":["להסביר במילים שלך: מה Backtesting באמת בודק?","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"13-2","week":13,"slot":2,"title":"כיצד לקרוא Equity Curve, Drawdown ו־Sharpe","type":"ניתוח ויישום","idea":"תשואה מצטברת לבדה אינה תמונה מלאה של אסטרטגיה. עקומת ההון מציגה התפתחות לאורך זמן, Drawdown מודד ירידה משיא קודם, ויחסים כמו Sharpe מציבים תשואה עודפת מול תנודתיות — תחת הנחות שיש לבדוק.","mechanism":"לדוגמה Drawdown= (שווי נוכחי/שיא מצטבר)−1. יש למדוד גם זמן התאוששות, התפלגות הפסדים, סיכון זנב וריכוז רווחים במספר עסקאות. Sharpe גבוה מבדיקה על מעט דגימות או עם החלקת מחירים עלול להיות מטעה. לכן תמיד מציגים מספר עסקאות, תקופת מדגם ורווח אחרי עלויות.","example":"הון עולה מ־10,000 ל־12,000 ואז יורד ל־9,000. הירידה מהשיא היא 25%−, גם אם בהמשך השוק חוזר לעלות.","limitation":"מדד יחיד אינו פוטר מבדיקת תרחישי קיצון. Drawdown מבוסס עבר לא מציב גבול להפסד עתידי.","practice":"השווה שתי עקומות הון עם תשואה סופית דומה אך Drawdown וזמן התאוששות שונים; נמק מה מתאים לסיבולת סיכון נמוכה.","question":"מה מתאר Maximum Drawdown?","choices":["ההפסד החמור ביותר משיא לשפל במדגם","הרווח הגבוה ביותר ביום","אחוז העסקאות המצליחות"],"correct":0,"explanation":"Drawdown מתייחס לירידה משיא הון היסטורי.","sources":["cmt","mit"],"objectives":["להסביר במילים שלך: כיצד לקרוא Equity Curve, Drawdown ו־Sharpe","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"13-3","week":13,"slot":3,"title":"AI לביקורת קוד Backtesting","type":"AI ומחקר","idea":"מודל AI יכול לקרוא פסאודו־קוד או קוד תוכנה ולחפש תקלות כגון שימוש בערך מהעתיד, חישוב אינדיקטור על דגימה חלקית או חוסר בעמלות. הוא לא מחליף בדיקת יחידה והרצה עצמאית.","mechanism":"בקש מהמודל לנסח רשימת בדיקות: האם פקודה מבוצעת אחרי האות? האם מניות שיצאו מהמדד נשמטו? האם יש טיפול במחירים חסרים ובפיצולים? האם עמלה נגבית בשני הצדדים? כיצד מחשבים תשואות בפוזיציה ומחוצה לה? לאחר מכן הרץ לפחות שלושה מקרי מבחן קטנים שניתן לחשב ידנית.","example":"בדוגמת שלושה ימים עם מחירים 100, 105, 102, אם האות נוצר בסוף יום שני, ביצוע במחיר 100 של יום ראשון הוא שגיאת זמן מובהקת.","limitation":"ביקורת לשונית של AI אינה מוכיחה שהקוד מתנהג נכון; כל טענה דורשת מבחן רץ.","practice":"כתוב בדיקות למצב ללא עסקאות, לעמלה גבוהה ולפער מחיר חד. רשום מה אמורה להיות התוצאה בכל מצב.","question":"מהו התפקיד המתאים ל-AI בתהליך?","choices":["לאשר רווחיות ללא הרצה","לייצר מקרי בדיקה ולזהות הנחות חשודות","להתחייב לתשואה עתידית"],"correct":1,"explanation":"AI תומך בבדיקת שגיאות, לא מאשר תוקף מדעי ללא אימות.","sources":["sullivan","cmt"],"objectives":["להסביר במילים שלך: AI לביקורת קוד Backtesting","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"14-1","week":14,"slot":1,"title":"In-Sample, Out-of-Sample ו־Walk Forward","type":"שוק ומחיר","idea":"כאשר בוחרים פרמטרים על אותם נתונים שבהם מדווחים על הצלחה, התוצאה בדרך כלל אופטימית מדי. חלוקת הנתונים לתקופת פיתוח ולתקופת מבחן שלא נגעה בבחירה מצמצמת את הבעיה.","mechanism":"חלוקת זמן צריכה להיות כרונולוגית: למשל נתוני 2015–2021 לפיתוח ו־2022–2025 למבחן. Walk-forward יוצר רצף של חלונות אימון ומבחן ומדמה עדכון תקופתי, תוך שמירה על סדר הזמנים. חשוב לא לחזור שוב ושוב ולשנות את הכללים אחרי צפייה בתוצאות מבחן — אחרת המבחן הופך לשלב פיתוח נוסף.","example":"בדקת 40 חלונות של ממוצעים על נתוני העבר ובחרת את הטוב ביותר. אם אותו חלון חלש בתקופה הנפרדת, ייתכן שהתאמת את הכלל לרעש.","limitation":"גם חלוקה אחת אינה ערובה להכללה. נדרשים דגימות מספיקות ושווקים שונים, ושמירה על פרוטוקול שקדם לתוצאות.","practice":"חלק סדרת נתונים לשני מדגמים כרונולוגיים. כתוב מראש אילו פרמטרים קובעים בחלק הראשון ואילו מדדים ידווחו בשני.","question":"למה צריך Out-of-Sample?","choices":["כדי לבחור שוב את הפרמטר המנצח","כדי לבדוק ביצוע על נתונים שלא שימשו לבחירת המודל","כדי להבטיח רווח"],"correct":1,"explanation":"מבחן נפרד בודק הכללה מעבר למדגם ההתאמה.","sources":["sullivan","brock"],"objectives":["להסביר במילים שלך: In-Sample, Out-of-Sample ו־Walk Forward","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"14-2","week":14,"slot":2,"title":"Data Snooping: איך מגלים יתרון שלא קיים?","type":"ניתוח ויישום","idea":"ניסוי שבו נבדקות מאות אסטרטגיות כמעט תמיד מוצא אחת שנראית מוצלחת במקרה. זו בעיית ריבוי בדיקות, הקרויה גם Data Snooping. מחקר Sullivan, Timmermann ו־White בחן כיצד אפשר לתקן חלק מההטיה.","mechanism":"נניח שבכל כלל חסר יתרון אמיתי, אך יש סיכוי של 5% לקבל מובהקות מדומה. אם בודקים 100 כללים בלי תיקון, הסיכוי למצוא לפחות \"מנצח\" מקרי גבוה מאוד. כדי לצמצם את ההטעיה צריך לדווח כמה ניסויים בוצעו, להגדיר היפותזות מראש, להשתמש בביקורת מתאימה ולבדוק מדגם חדש. אין להסתפק בגרף של הכלל הזוכה.","example":"בדקת 5 שילובי MA? רשום חמישה. בדקת 500? רשום 500. אי אפשר לפרסם רק את השילוב שהצליח הכי טוב.","limitation":"מובהקות סטטיסטית אינה זהה לכדאיות מסחרית אחרי עלויות. גם תיקון לריבוי בדיקות לא מציל נתונים גרועים.","practice":"בנה יומן ניסויים שמכיל מזהה גרסה, פרמטרים, תאריך ריצה, מספר בדיקות ותוצאה במדגם חדש.","question":"מהו Data Snooping?","choices":["הטיה בעקבות ניסוי ובחירת כללים רבים על אותו מדגם","תנודתיות טבעית של נר","מדידה של מחזור מסחר"],"correct":0,"explanation":"בחירת המנצח מתוך ניסיונות רבים מעוותת את הערכת היתרון.","sources":["sullivan","lo-paper"],"objectives":["להסביר במילים שלך: Data Snooping: איך מגלים יתרון שלא קיים?","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"14-3","week":14,"slot":3,"title":"AI כעוזר למתודולוגיית מחקר","type":"AI ומחקר","idea":"במחקר פיננסי התפקיד המועיל של AI הוא לשפר את התכנון ואת התיעוד. אפשר לבקש ממנו לכתוב תבנית פרוטוקול ולהצביע על מקומות שבהם החוקרים עלולים להציץ בתוצאה לפני קיבוע השערה.","mechanism":"הגדר השערת אפס, השערה חלופית, נתונים, משתנה תוצאה, כללי סינון, עלויות, חלוקה בזמן ורשימת בדיקות. בקש הצעה לבנצ׳מרק פשוט ולהערכת רגישות. שים לב שלא כל מדד סטטיסטי מתאים לסדרת תשואות תלויה בזמן, ושהמודל אינו מוסמך לטעון למובהקות אם לא בוצע חישוב נכון.","example":"למחקר פריצת שיא 20 ימים, הצעה טובה תפרט האם כניסה היא ביום שלאחר הפריצה, אילו מניות נכללות ואילו עלויות משמשות בחישוב.","limitation":"AI עשוי להמציא תוצאת p-value; דרוש קוד בר־הרצה או חישוב ידני למקרי מבחן קטנים.","practice":"בקש מ־AI לבנות רשימת ביקורת בת 12 סעיפים לבדיקה היסטורית. בצע בעצמך שלוש בדיקות על דוגמה.","question":"מהי תוצאה תקינה מתהליך AI מחקרי?","choices":["פרוטוקול מתועד וניתן לבדיקה","תחזית מדויקת ללא נתונים","הבטחה שהבנצ׳מרק יובס"],"correct":0,"explanation":"הערך הוא בפרוטוקול עקבי, לא בהבטחת מסקנה.","sources":["sullivan","cfa"],"objectives":["להסביר במילים שלך: AI כעוזר למתודולוגיית מחקר","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"15-1","week":15,"slot":1,"title":"הכנסות, רווח, תזרים מזומנים ומאזן","type":"שוק ומחיר","idea":"ניתוח טכני מתמקד במחירי שוק, אך משקיע צריך להבין גם את העסק שמאחוריהם. הכנסות מודדות מכירות, רווח נקי משקף הכנסות פחות הוצאות לפי כללי חשבונאות, ותזרים מזומנים מודד תנועות מזומנים בפועל.","mechanism":"בדוח רווח והפסד מחפשים צמיחה ושולי רווח; במאזן מסתכלים על מזומנים, חוב והון; בדוח תזרים בוחנים תזרים מפעילות שוטפת והשקעות הוניות. חברה יכולה לדווח רווח חשבונאי ולסבול ממחסור בנזילות, ולהפך. השוואת שנים דורשת הבחנה בין פעילות חוזרת לאירועים חד־פעמיים.","example":"חברה מוכרת ב־100 מיליון, רווח נקי 10 מיליון אך תזרים פעילות 2 מיליון. אין להסיק אוטומטית שמדובר בחברה גרועה; צריך לבדוק את הסיבות לפער.","limitation":"נתוני EPS והכנסות מאתרים משניים עלולים להיות מעוגלים או שונים בהגדרה. בעת מחקר פנה לדוח המקורי.","practice":"אתר בדוח 10-K שורת הכנסות, רווח נקי ותזרים תפעולי; כתוב מה השתנה בין שתי שנים ומדוע.","question":"מה לא ניתן להסיק מהכנסות בלבד?","choices":["כמה מכרה החברה","מה הרווחיות והתזרים האמיתיים","האם המכירות עלו"],"correct":1,"explanation":"הכנסות הן תחילת הסיפור; רווחיות ותזרים הם רכיבים נוספים.","sources":["sec","damodaran"],"objectives":["להסביר במילים שלך: הכנסות, רווח, תזרים מזומנים ומאזן","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"15-2","week":15,"slot":2,"title":"שווי חברה מול מחיר מניה: מבוא להערכת שווי","type":"ניתוח ויישום","idea":"מחיר מניה הוא נתון שוק; שווי כלכלי הוא אומדן תלוי הנחות. משקיעים משתמשים במכפילים ובהיוון תזרימים כדי לשאול כמה משלם השוק ביחס לרווחים ולתזרים צפוי.","mechanism":"מכפיל רווח (P/E) מחלק מחיר מניה ברווח למניה; הוא עשוי להיות לא אינפורמטיבי בחברות מפסידות או רווחים חד־פעמיים. במודל DCF מעריכים תזרימים עתידיים ומהו שיעור ההיוון המתאים לסיכונם. שינויים קטנים בהנחות צמיחה והיוון יכולים לגרום לשינויים גדולים באומדן. לכן עדיף להציג טווח תרחישים ולא מספר ״מדויק״ אחד.","example":"אם מחיר מניה 50 דולר והרווח למניה 5 דולר, P/E=10. זה לא אומר בהכרח שהמניה זולה בלי לבדוק איכות רווחים, סיכון וצמיחה צפויה.","limitation":"הערכת שווי היא מודל, לא עובדה נצפית. אל תערבב תוצאות של תרחישים אופטימיים עם הצעות ודאיות.","practice":"חשב P/E של שתי חברות והשווה האם איכות הרווח ושיעור הצמיחה מצדיקים את ההבדל — כתרגיל, לא כהמלצת השקעה.","question":"מהו P/E?","choices":["מחיר חלקי רווח למניה","נפח חלקי מחיר","מכפיל שמבטיח תשואה"],"correct":0,"explanation":"P/E מתאר יחס בין מחיר השוק לרווח המדווח למניה.","sources":["damodaran","sec"],"objectives":["להסביר במילים שלך: שווי חברה מול מחיר מניה: מבוא להערכת שווי","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"15-3","week":15,"slot":3,"title":"AI לקריאת דוחות עם הפניות מדויקות","type":"AI ומחקר","idea":"מודל שפה יכול לחלץ טבלת מדדים מדוח חברה, אך אמינותו תלויה בקובץ, בהגדרות המדד ובאימות ידני. בקש תמיד ציון של סעיף, עמוד, מטבע ותקופה עבור כל מספר.","mechanism":"התהליך הנכון: מורידים מסמך 10-K מקורי, מגדירים חמש שורות למעקב, מבקשים חילוץ עם ציטוט עמודים, בודקים שתי שורות מול הטבלה המקורית ומחשבים שינוי שנתי. רק לאחר מכן מבקשים הסבר אפשרי לשינוי ומסמנים אותו כהשערה. את הפרשנות משווים להסברי הנהלת החברה ולסיכונים שמפורטים בדוח.","example":"AI מציין הכנסות של 50 מיליארד במקום 5.0 מיליארד בגלל יחידות מדידה. בדיקה של הכותרת \"in millions\" לפני חישוב מונעת טעות פי עשרה.","limitation":"יש דוחות עם טבלאות סרוקות וערכים לא מלאים; אם חילוץ נכשל יש לסמן חסר ולא לנחש.","practice":"מצא שתי שורות בדוח ובנה טבלה עם מספר, עמוד, שנה, יחידה, נוסחת חישוב ואימות ידני.","question":"מה צריך להופיע לצד כל נתון ש-AI חילץ?","choices":["עמוד, תקופה ויחידות מדידה","רק צבע חיובי או שלילי","דירוג קנייה"],"correct":0,"explanation":"ציון מקור ויחידות מאפשר לבקר את הנתון לפני הפרשנות.","sources":["sec","damodaran"],"objectives":["להסביר במילים שלך: AI לקריאת דוחות עם הפניות מדויקות","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"16-1","week":16,"slot":1,"title":"להשוות שווקים: ארה״ב, אירופה, יפן, הודו וישראל","type":"שוק ומחיר","idea":"שוקי מניות שונים בשעות מסחר, מטבעות, הרכב מדדים, ריכוז סקטוריאלי ורגולציה. שני מדדים עם תשואה דומה במטבע מקומי עשויים להניב למשקיע שקלי תוצאות שונות בגלל תנועות מטבע.","mechanism":"לפני ניתוח השוואתי הגדר בורסה, מדד, גרסת מדד הכוללת או אינה כוללת דיבידנדים, מטבע, לוח שנה ודרך המרת תשואות. יש להבחין בין מחיר של ETF שנסחר בארה״ב לבין מדד הבסיס שלו הנסחר באזור זמן שונה. כשבודקים התנהגות ביום מסוים, אירועים שאירעו לאחר סגירת שוק אחר לא היו זמינים שם.","example":"מדד ביפן עלה 10% ביין, ובאותה תקופה היין נחלש 8% מול דולר. תשואה דולרית בקירוב היא 1.10×0.92−1=1.2%, לפני עמלות ומסים.","limitation":"השוואת תשואות ללא מטבע, דיבידנדים ועלויות עלולה להיות מטעה. נתונים מקורות שונים עשויים להשתמש בשעות חיתוך שונות.","practice":"בנה טבלת חמישה שווקים: שעות מסחר, מטבע, מדד מייצג, שני ענפים מרכזיים ומקור נתונים.","question":"מה עשוי לשנות תשואה למשקיע ישראלי מעבר למדד המקומי?","choices":["שער חליפין ותשואה כוללת","צבע הלוגו של הבורסה","מספר נרות בגרף"],"correct":0,"explanation":"מטבע ודיבידנדים משפיעים על התשואה במטבע המשקיע.","sources":["investor","mit"],"objectives":["להסביר במילים שלך: להשוות שווקים: ארה״ב, אירופה, יפן, הודו וישראל","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"16-2","week":16,"slot":2,"title":"ריבית, אינפלציה, סקטורים וקשרי שוק","type":"ניתוח ויישום","idea":"מחירי מניות אינם פועלים בחלל ריק. ריבית, אינפלציה, שערי חליפין ומחירי אנרגיה משפיעים על עלויות מימון, ביקוש והערכת שווי; השפעתם שונה בין חברות וענפים.","mechanism":"כאשר ריבית עולה, תזרימים עתידיים רחוקים עשויים להיות שווים פחות בהיוון, אך השפעה בפועל תלויה גם בציפיות שכבר היו במחיר. בנקים, יזמים ותעשיות שונות מגיבים אחרת לשינויים. ניתוח טכני יכול לתאר את תנועת המחיר, ומחקר מאקרו יכול לספק הקשר, אך שילובם צריך להיעשות בזהירות וללא סיפור בדיעבד.","example":"חברת צמיחה עם רוב הרווחים העתידיים עשויה להיות רגישה יותר לשינוי בשיעור היוון מאשר חברה שמייצרת תזרים קרוב, בהנחות דומות.","limitation":"קורלציות בין נכסים משתנות בזמן, במיוחד במשברים; פיזור שנראה טוב בעבר עלול להתכווץ כשהכי צריך אותו.","practice":"בחר אירוע החלטת ריבית היסטורי. השווה שלושה סקטורים ביום האירוע ובחודש שאחריו, וסמן את המגבלות.","question":"מהי טעות נפוצה בפירוש אירוע מאקרו?","choices":["להשוות סקטורים שונים","להניח שהתגובה נגרמה רק מהכותרת בלי לבדוק ציפיות","לבדוק את תאריך ההחלטה"],"correct":1,"explanation":"המחירים מגיבים לציפיות ולהפתעות, לא רק לנתון כפי שפורסם.","sources":["yale","mit"],"objectives":["להסביר במילים שלך: ריבית, אינפלציה, סקטורים וקשרי שוק","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"16-3","week":16,"slot":3,"title":"AI להשוואה בינלאומית עם נרמול תקין","type":"AI ומחקר","idea":"כאשר משווים מניות מישראל, יפן וארה״ב, AI עשוי לערבב מטבעות, מועדי מסחר ונתונים מתואמים ולא מתואמים. שימוש ראוי במודל מתחיל בשאלות על איכות הנתונים.","mechanism":"בקש ממנו ליצור סכימת טבלה אחידה: תאריך לפי אזור זמן, סימול ובורסה, מטבע, מחיר מתואם, שער המרה, תשואה במטבע מקור ותשואה במטבע יעד. דרוש פירוט נוסחת המרה והסבר האם דיבידנדים כלולים. בקש לכל היותר מסקנה תיאורית כאשר אין מספיק מידע לבדיקת מובהקות.","example":"אם מחיר מניה עלה 5% ביורו והיורו התחזק 3% מול שקל, התשואה השקלית בקירוב היא 1.05×1.03−1=8.15%.","limitation":"שערי חליפין אינם תמיד זמינים באותו חיתוך זמן של מסחר המניה; סטייה זו יכולה להשפיע על תשואה יומית.","practice":"כתוב prompt עם כללי נרמול מחייבים ובצע דוגמה ידנית אחת של המרת תשואה.","question":"למה לא משווים מחירי מניות משווקים שונים ישירות?","choices":["כי המטבע והיחידה שונים","כי כל מניה חייבת להיות שווה","כי AI תמיד יודע את השער הנכון"],"correct":0,"explanation":"מחיר נומינלי אינו מדד השוואתי לתמחור או תשואה.","sources":["mit","sec"],"objectives":["להסביר במילים שלך: AI להשוואה בינלאומית עם נרמול תקין","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"17-1","week":17,"slot":1,"title":"פיזור מול ריכוז: למדוד חשיפה אמיתית","type":"שוק ומחיר","idea":"מספר מניות גדול בתיק לא בהכרח יוצר פיזור. אם רוב החברות חשופות לאותה ריבית, סקטור או גורם סיכון, הן יכולות לרדת יחד למרות שמות שונים.","mechanism":"חישוב פיזור מתחיל במשקל כל נכס, ענף, מדינה ומטבע. את הקורלציות מחשבים על תקופות היסטוריות תוך הכרה בכך שהן אינן קבועות. קרן שוק רחבה יכולה להיות מרוכזת במספר חברות גדולות לפי שווי שוק. כמו כן, החזקת כמה ETF חופפים יכולה ליצור חשיפה כפולה לאותן חברות.","example":"תיק מחזיק שלוש קרנות טכנולוגיה שונות. אף שיש בו שלושה מוצרים, חפיפת ההחזקות עשויה ליצור חשיפה גבוהה לאותן חברות שבבים ותוכנה.","limitation":"פיזור אינו מבטיח רווח או הגנה מפני ירידות כלל־שוקיות. קשר בין נכסים נוטה להשתנות דווקא בתקופות לחץ.","practice":"בדוק את חמש ההחזקות הגדולות בכל אחת משלוש קרנות וחשב חשיפה מצטברת לשתי חברות החוזרות בכולן.","question":"מה משקף פיזור טוב יותר?","choices":["מספר סמלים בלבד","שילוב גורמי סיכון שונים ומשקלים","מספר עמודים בדוח"],"correct":1,"explanation":"חשיפות חופפות יכולות לצמצם את אפקט הפיזור.","sources":["diversification","cfa"],"objectives":["להסביר במילים שלך: פיזור מול ריכוז: למדוד חשיפה אמיתית","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"17-2","week":17,"slot":2,"title":"תוכנית משבר: תרחישי הפסד, נזילות ומשמעת","type":"ניתוח ויישום","idea":"בתקופות משבר הטעות הקשה היא ליצור תוכנית תוך כדי לחץ. תוכנית מראש אינה מונעת ירידות, אך מספקת מסגרת לחשיבה על חשיפה, כרית נזילות ופעולות אפשריות.","mechanism":"הגדר מה יקרה לתיק אם שוק המניות ייפול 20%, אם המטבע ינוע 10% או אם שתי פוזיציות ירדו יחד. שאל מהן התחייבויות המזומן שלך, מה טווח ההשקעה ומהם הכללים שיגרמו להפחתת סיכון או להמשך החזקה. יש להבחין בין משקיע ארוך טווח לבין סוחר קצר טווח; לשניהם מדדי הצלחה שונים.","example":"תיק של 30,000 דולר עם 80% מניות: ירידה של 25% בחלק המנייתי, ללא שינוי ביתר, מפחיתה בערך 6,000 דולר מהתיק, כלומר 20%.","limitation":"בדיקת תרחיש אינה הסתברות. אל תתכנן על סמך משבר אחד בלבד ואל תניח שנכסים ״בטוחים״ תמיד נשארים יציבים.","practice":"בנה שלושה תרחישי לחץ וכתוב תגובת ברירת מחדל מראש; רשום גם מה יגרום לך לא לפעול.","question":"מה היתרון של תוכנית כתובה מראש?","choices":["מבטיחה שלא יהיו הפסדים","מפחיתה החלטות מאולתרות בזמן לחץ","מנבאת את מועד המשבר"],"correct":1,"explanation":"תכנון משמעת מביא לתהליך עקבי יותר, לא לתוצאה מובטחת.","sources":["diversification","yale"],"objectives":["להסביר במילים שלך: תוכנית משבר: תרחישי הפסד, נזילות ומשמעת","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"17-3","week":17,"slot":3,"title":"AI לביקורת ריכוז ותרחישי סיכון","type":"AI ומחקר","idea":"AI יכול לסייע בהכנת טבלת סיכונים והצלבות בין מוצרים, אבל הוא לא יודע מה אתה מחזיק בלי נתונים שהזנת ואינו אמור לקבל גישה לסיסמאות או למפתחות מסחר.","mechanism":"תן רשימת נכסים ומחירים דמיוניים ללא פרטי חשבון, ובקש סיכום של משקלי ענפים, חפיפות אפשריות, השפעת תרחיש מטבע ורשימת נתונים חסרים. ודא חישוב סכומי משקלים ל־100% והשווה מול טבלה ידנית. אם אין מידע על אחזקות ה־ETF, דרוש שהמודל יסמן חסר במקום להמציא.","example":"שתי קרנות שכל אחת מחזיקה 10% בחברה מסוימת ומשקלן בתיק 30% ו־20%, יוצרות חשיפה של 0.30×0.10+0.20×0.10=5% מהתיק לחברה זו.","limitation":"ללא דיווח אחזקות מעודכן, AI לא יכול לכמת חפיפה בדיוק. אין לשתף מידע רגיש שאינו דרוש לתרגיל.","practice":"צור תיק הדגמה של חמישה נכסים, חשב משקלים וסמן שלושה מוקדי ריכוז בתיק.","question":"מה עושים כשאין נתון על אחזקות קרן?","choices":["מנחשים לפי שם הקרן","מסמנים חסר ומחפשים דוח קרן","מניחים שאין חפיפה"],"correct":1,"explanation":"חוסר מידע צריך להיות שקוף ולא מוסווה כהנחה.","sources":["cfa","diversification"],"objectives":["להסביר במילים שלך: AI לביקורת ריכוז ותרחישי סיכון","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"18-1","week":18,"slot":1,"title":"פרויקט מסכם א׳: שאלת מחקר ומדגם","type":"שוק ומחיר","idea":"פרויקט מסכם טוב אינו מתחיל מבחירת מניה ״מנצחת״; הוא מתחיל בשאלה שניתן לבדוק באופן הוגן. למשל: האם כלל חציה של ממוצעים נותן תוצאה טובה יותר מהחזקה פסיבית במניות סחירות במדגם נתון, לאחר עלויות?","mechanism":"כתוב רקע קצר שמציג את המנגנון האפשרי, הסברים חלופיים וממצאי מחקר קודמים. הגדר אוכלוסייה, מדגם, טווח תאריכים, מקור מחירים, מועד היווצרות האות וכללי הוצאה. חלק את הנתונים למדגם פיתוח ומבחן. סכם את מה שאתה יודע ואת מה שעוד אינך יודע, לפני כל הרצה.","example":"שאלה חלשה: ״האם MA20 עובד?״. שאלה חזקה: ״האם כלל MA20/MA60 על מניות S&P 500 שהיו במדד בתחילת כל שנה גובר על Buy-and-Hold בתקופת מבחן, אחרי עלות כניסה ויציאה של 0.15%?״","limitation":"אם אין לך נתונים היסטוריים של חברות שנמחקו, קיימת סכנת Survivorship Bias ויש לציין אותה ביושר.","practice":"הגש עמוד מחקר: שאלה, השערת אפס, מקורות, נתוני מדגם, מדדי תוצאה ומגבלות.","question":"מה נחשב ניסוח מחקר טוב?","choices":["תוצאה ידועה מראש","השערה מדידה ותנאי מבחן מוגדרים","החלטה לפי גרף שנבחר בדיעבד"],"correct":1,"explanation":"מחקר מתחיל מפרוטוקול שניתן לבקר, לא ממסקנה.","sources":["sullivan","brock","cmt"],"objectives":["להסביר במילים שלך: פרויקט מסכם א׳: שאלת מחקר ומדגם","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"18-2","week":18,"slot":2,"title":"פרויקט מסכם ב׳: תוצאות, ביקורת ואתיקה","type":"ניתוח ויישום","idea":"אחרי הרצת המחקר מציגים את כל התוצאות — גם כישלונות. תוצאה חיובית אינה מלמדת בהכרח שיש יתרון אמיתי, ותוצאה שלילית אינה הופכת את עצם המחקר לחסר ערך.","mechanism":"דוח מקצועי כולל תשואות גולמיות ונטו, עמלות, מספר עסקאות, מקסימום Drawdown, השוואה לבנצ׳מרק, רגישות לפרמטרים ותוצאות Out-of-Sample. יש לתעד כל ניסוי שבוצע ולדווח אם התזה שונתה אחרי הסתכלות בנתונים. אתיקה מחייבת להימנע מציטוטים מזויפים ומכותרות מטעות כגון ״90% הצלחה״ ללא הגדרות.","example":"אם אסטרטגיה מציגה +18% לפני עלויות, +8% אחרי עלויות ומדד הייחוס +12%, הדוח צריך להבליט את ההשוואה הנטו, לא רק את 18%.","limitation":"גם מבחן נקי אינו תחזית ודאית. אל תציג ביצועי עבר כאילו מדובר בתשואה שתתקבל בחשבון אמיתי.","practice":"כתוב סיכום בן 250 מילים עם טבלה של חמישה מדדים, שלוש מגבלות, וראיה אחת נגד התזה המקורית.","question":"מה חייב להופיע בדוח אמין?","choices":["רק העסקה המוצלחת ביותר","תוצאות נטו, בנצ׳מרק ומגבלות","רק צבע האינדיקטור"],"correct":1,"explanation":"דיווח שקוף מתייחס גם לעלויות, לסיכון ולתוצאות שאינן תומכות בתזה.","sources":["sullivan","cmt","cfa"],"objectives":["להסביר במילים שלך: פרויקט מסכם ב׳: תוצאות, ביקורת ואתיקה","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45},{"id":"18-3","week":18,"slot":3,"title":"פרויקט מסכם ג׳: הצגה והמשך למידה עצמאי","type":"AI ומחקר","idea":"לומד עצמאי אינו זקוק להבטחת רווח. הוא זקוק לשיטה להשוות הסברים לעובדות, לתעד החלטות, לבחון כללים ולדעת מתי הנתונים אינם מספיקים. זהו הבסיס להתקדמות לאחר המסלול.","mechanism":"הכן מצגת או דוח בן חמישה חלקים: השאלה, המחקר הקיים, השיטה, התוצאות והמגבלות. הוסף נספח מקורות עם קישורים ראשוניים ותאריכי בדיקה. סיים בתוכנית לימוד לשלושה חודשים: נושא אחד להעמקה, הרגל תיעוד שבועי ודרך לבדוק שינוי ביכולת בלי להשתמש רק בתשואה. למד לזהות מתי יש להימנע ממסחר כי הנחות האסטרטגיה אינן מתקיימות.","example":"תלמיד שמסיים את המסלול מסוגל להסביר למה כלל מסוים נכשל, מה הייתה ההטיה האפשרית ואיזו בדיקה נדרשת להמשך — גם אם התיק לא הניב רווח.","limitation":"אין כאן הסמכה מקצועית, המלצת השקעה או גישה בלעדית למחקר. שימוש חכם בספרות הוא ביקורתי, לא העתקת מסקנות.","practice":"הגש דוח סופי עם רשימת מקורות וביקורת עמיתים עצמית: חמש שאלות קשות שעליך לענות עליהן לפני מסחר אמיתי.","question":"מהי התוצאה הרצויה ממסלול זה?","choices":["הבטחה לחזות מחיר עתידי","יכולת ללמוד, לבקר ולבדוק החלטות בעקביות","שמירת 54 כותרות בלי תרגול"],"correct":1,"explanation":"הצלחה בלמידה היא שיטה אמינה ומתועדת, לא ניבוי ודאי.","sources":["cmt","mit","yale","sullivan"],"objectives":["להסביר במילים שלך: פרויקט מסכם ג׳: הצגה והמשך למידה עצמאי","ליישם כלל ברור על דוגמה או סדרת מחירים בלי להניח מה יקרה בעתיד","לזהות מקור מידע, מגבלה והשלכה לסיכון"],"duration":45}]};
